        y = a << 1;
        carry = a[WIDTH-1];
      end
      3'd6: begin
        y = a >> 1;
        carry = a[0];
      end
      3'd7: y = (a < b) ? 1 : 0;
      default: y = 0;
    endcase
  end

  assign zero = (y == 0);
endmodule
