                if (prio_word * 8 + wj < NUM_SRC)
                  prio_flat[(prio_word*8 + wj)*PRIO_BITS +: PRIO_BITS] <= wdata[4*wj +: PRIO_BITS];
        endcase
      end
    end
  end
