module priority_encoder #(
  parameter N = 8
) (
  input      [N-1:0]         req,
  output reg [$clog2(N)-1:0] idx,
  output                     valid,
  output     [N-1:0]         onehot
);
  integer i;
  reg [N-1:0] onehot_reg;

  assign valid  = |req;
  assign onehot = onehot_reg;

  always @* begin
    idx        = 0;
    onehot_reg = {N{1'b0}};

    // Iterating upward lets each higher-numbered request overwrite
    // the index of any lower-numbered request.
    for (i = 0; i < N; i = i + 1) begin
      if (req[i])
        idx = i;
    end

    if (valid)
      onehot_reg[idx] = 1'b1;
  end
endmodule

