  always @(*) begin
    best_valid = 1'b0;
    best_idx   = 0;
    best_prio  = 0;
    for (k = 0; k < N; k = k + 1)
      if (eligible[k] && prio_flat[k*PRIO_BITS +: PRIO_BITS] > best_prio) begin
