    wire            tmr_periodic    = tmr_cfg[2];

    reg [31:0]      tmr_reg;
    reg [PRW-1:0]   pr_reg;

    wire            start_pulse;
    reg             tmr_run;
    reg             fault_reg;

    ef_util_ped TMREN_PE (
        .clk(clk),
        .in(tmr_en),
        .out(start_pulse)
