    best_idx   = 0;
    best_prio  = 0;

    // Iterate in source order and replace the current best only for a
    // strictly higher priority. This preserves the lowest index on ties.
    for (i = 0; i < N; i = i + 1) begin
      if (eligible[i] &&
          (prio_flat[i*PRIO_BITS +: PRIO_BITS] > best_prio)) begin
        best_valid = 1'b1;
        best_idx   = i;
        best_prio  = prio_flat[i*PRIO_BITS +: PRIO_BITS];
