module EF_TMR32 #(parameter PRW = 16,
                                PWM_FAULT_CLR_C0 = 16'hA539,
                                PWM_FAULT_CLR_C1 = 16'hA953 
)
(
    input   wire            clk,
    input   wire            rst_n,

    input   wire            tmr_en,
    input   wire            tmr_start,
    input   wire            pwm0_en,
    input   wire            pwm1_en,
    input   wire [31:0]     tmr_reload,
    input   wire [31:0]     cmpx,
    input   wire [31:0]     cmpy,
    input   wire [PRW-1:0]  prescaler,
    input   wire [ 2:0]     tmr_cfg,     // [2]: Periodic/OneShot; [1:0]: 10: Up, 01: Down, 11: Up/Down
    input   wire [11:0]     pwm0_cfg,
    input   wire [11:0]     pwm1_cfg,
    input   wire            pwm0_inv,
    input   wire            pwm1_inv,
    input   wire [ 7:0]     pwm_dt,
    input   wire [15:0]     pwm_fault_clr,
    input   wire            pwm_dt_en,

    output  wire [31:0]     tmr,
    output  wire            matchx_flag,
    output  wire            matchy_flag,
    output  wire            timeout_flag,

    input   wire            pwm_fault,
    output  wire            pwm0,
    output  wire            pwm1
);
  reg [PRW-1:0] pr;
  wire tick = (pr == {PRW{1'b0}});

  reg [31:0] tmr_reg;
  reg        count_down;
  reg        running;

  wire start_pulse;
  ef_util_ped start_detector (
      .clk(clk),
      .in(tmr_en),
      .out(start_pulse)
  );

  assign tmr = tmr_reg;
  assign matchx_flag = (tmr_reg == cmpx);
  assign matchy_flag = (tmr_reg == cmpy);
  assign timeout_flag = count_down ? (tmr_reg == 32'd0) :
                                      (tmr_reg == tmr_reload);

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
      pr <= {{(PRW-1){1'b0}}, 1'b1};
    else if (!tmr_en)
      pr <= prescaler;
    else if (pr == {PRW{1'b0}})
      pr <= prescaler;
    else
      pr <= pr - {{(PRW-1){1'b0}}, 1'b1};
  end

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      tmr_reg   <= 32'd0;
      count_down <= 1'b0;
      running   <= 1'b0;
    end else begin
      if (start_pulse) begin
        if (tmr_cfg[1:0] == 2'b01) begin
          tmr_reg <= tmr_reload;
          count_down <= 1'b1;
        end else begin
          tmr_reg <= 32'd0;
          count_down <= 1'b0;
        end
        running <= 1'b1;
      end else begin
        if (tick) begin
          case (tmr_cfg[1:0])
            2'b11: begin
              if (!count_down && (tmr_reg == (tmr_reload - 32'd1)))
                count_down <= 1'b1;
              else if (count_down && (tmr_reg == 32'd1))
                count_down <= 1'b0;
            end
            2'b01: count_down <= 1'b1;
            default: count_down <= 1'b0;
          endcase

          if (tmr_en && running) begin
            if (tmr_start && (tmr_cfg[1:0] == 2'b01)) begin
              tmr_reg <= tmr_reload;
            end else if (tmr_start &&
                         ((tmr_cfg[1:0] == 2'b10) ||
                          (tmr_cfg[1:0] == 2'b11))) begin
              tmr_reg <= 32'd0;
            end else begin
              case (tmr_cfg[1:0])
                2'b11: begin
                  if (count_down)
                    tmr_reg <= tmr_reg - 32'd1;
                  else
                    tmr_reg <= tmr_reg + 32'd1;

                  if (!tmr_cfg[2] && count_down && (tmr_reg == 32'd1))
                    running <= 1'b0;
                end

                2'b01: begin
                  if (tmr_reg == 32'd0) begin
                    if (tmr_cfg[2])
                      tmr_reg <= tmr_reload;
                  end else begin
                    tmr_reg <= tmr_reg - 32'd1;
                  end

                  if (!tmr_cfg[2] && (tmr_reg == 32'd1))
                    running <= 1'b0;
                end

                2'b10: begin
                  if (tmr_reg == tmr_reload) begin
                    if (tmr_cfg[2])
                      tmr_reg <= 32'd0;
                  end else begin
                    tmr_reg <= tmr_reg + 32'd1;
                  end
                end

                default: begin
                  tmr_reg <= tmr_reg;
                end
              endcase
            end
          end
        end
      end
    end
  end

  wire dir_up = ~count_down;
  wire e0 = (tmr_reg == 32'd0) &&
            (tmr_reg != cmpx) &&
            (tmr_reg != cmpy) &&
            (tmr_reg != tmr_reload);
  wire e1 = dir_up &&
            (tmr_reg == cmpx) &&
            (tmr_reg != 32'd0) &&
            (tmr_reg != cmpy) &&
            (tmr_reg != tmr_reload);
  wire e2 = dir_up &&
            (tmr_reg == cmpy) &&
            (tmr_reg != 32'd0) &&
            (tmr_reg != cmpx) &&
            (tmr_reg != tmr_reload);
  wire e3 = (tmr_reg == tmr_reload) &&
            (tmr_reg != 32'd0) &&
            (tmr_reg != cmpx) &&
            (tmr_reg != cmpy);
  wire e4 = count_down &&
            (tmr_reg == cmpy) &&
            (tmr_reg != 32'd0) &&
            (tmr_reg != cmpx) &&
            (tmr_reg != tmr_reload);
  wire e5 = count_down &&
            (tmr_reg == cmpx) &&
            (tmr_reg != 32'd0) &&
            (tmr_reg != cmpy) &&
            (tmr_reg != tmr_reload);
  wire [5:0] pwm_event = {e5, e4, e3, e2, e1, e0};

  reg [1:0] pwm0_action;
  reg [1:0] pwm1_action;
  always @* begin
    pwm0_action = 2'b00;
    pwm1_action = 2'b00;
    case (pwm_event)
      6'b000001: begin
        pwm0_action = pwm0_cfg[1:0];
        pwm1_action = pwm1_cfg[1:0];
      end
      6'b000010: begin
        pwm0_action = pwm0_cfg[3:2];
        pwm1_action = pwm1_cfg[3:2];
      end
      6'b000100: begin
        pwm0_action = pwm0_cfg[5:4];
        pwm1_action = pwm1_cfg[5:4];
      end
      6'b001000: begin
        pwm0_action = pwm0_cfg[7:6];
        pwm1_action = pwm1_cfg[7:6];
      end
      6'b010000: begin
        pwm0_action = pwm0_cfg[9:8];
        pwm1_action = pwm1_cfg[9:8];
      end
      6'b100000: begin
        pwm0_action = pwm0_cfg[11:10];
        pwm1_action = pwm1_cfg[11:10];
      end
      default: begin
        pwm0_action = 2'b00;
        pwm1_action = 2'b00;
      end
    endcase
  end

  reg pwm0_state;
  reg pwm1_state;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      pwm0_state <= 1'b0;
      pwm1_state <= 1'b0;
    end else if (tick && pwm0_en) begin
      if (pwm_fault)
        pwm0_state <= 1'b0;
      else begin
        case (pwm0_action)
          2'b01: pwm0_state <= 1'b0;
          2'b10: pwm0_state <= 1'b1;
          2'b11: pwm0_state <= ~pwm0_state;
          default: pwm0_state <= pwm0_state;
        endcase
      end
    end
  end

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      pwm1_state <= 1'b0;
    end else if (tick && pwm1_en) begin
      if (pwm_fault)
        pwm1_state <= 1'b0;
      else begin
        case (pwm1_action)
          2'b01: pwm1_state <= 1'b0;
          2'b10: pwm1_state <= 1'b1;
          2'b11: pwm1_state <= ~pwm1_state;
          default: pwm1_state <= pwm1_state;
        endcase
      end
    end
  end

  reg [7:0] deadtime_count;
  reg       pwm0_delayed;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      deadtime_count <= 8'd0;
      pwm0_delayed <= 1'b0;
    end else if (tick) begin
      if (deadtime_count == 8'd0)
        deadtime_count <= pwm_dt;
      else
        deadtime_count <= deadtime_count - 8'd1;

      if (deadtime_count == 8'd0)
        pwm0_delayed <= pwm0_state;
    end
  end

  reg pwm0_out_reg;
  reg pwm1_out_reg;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      pwm0_out_reg <= 1'b0;
      pwm1_out_reg <= 1'b0;
    end else if (pwm_dt_en) begin
      pwm0_out_reg <= pwm0_delayed & pwm0_state;
      pwm1_out_reg <= ~pwm0_delayed & ~pwm0_state;
    end else begin
      pwm0_out_reg <= pwm0_state;
      pwm1_out_reg <= pwm1_state;
    end
  end

  reg fault_armed;
  reg fault_latched;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      fault_armed <= 1'b0;
      fault_latched <= 1'b0;
    end else begin
      if (pwm_fault_clr == PWM_FAULT_CLR_C0)
        fault_armed <= 1'b1;
      else if (pwm_fault_clr == PWM_FAULT_CLR_C1)
        fault_armed <= 1'b0;

      if (pwm_fault)
        fault_latched <= 1'b1;
      else if (fault_armed && (pwm_fault_clr == PWM_FAULT_CLR_C1))
        fault_latched <= 1'b0;
    end
  end

  assign pwm0 = (pwm0_out_reg ^ pwm0_inv) &
                ~pwm_fault & ~fault_latched & pwm0_en;
  assign pwm1 = (pwm1_out_reg ^ pwm1_inv) &
                ~pwm_fault & ~fault_latched & pwm1_en;

endmodule

