`default_nettype    none                                                   

module EF_TMR32 #(parameter PRW = 16,
                                PWM_FAULT_CLR_C0 = 16'hA539,
                                PWM_FAULT_CLR_C1 = 16'hA953 
)
(
    input   wire            clk,
    input   wire            rst_n,

    input   wire            tmr_en,
    input   wire            tmr_start,
    input   wire            pwm0_en,
    input   wire            pwm1_en,
    input   wire [31:0]     tmr_reload,
    input   wire [31:0]     cmpx,
    input   wire [31:0]     cmpy,
    input   wire [PRW-1:0]  prescaler,
    input   wire [ 2:0]     tmr_cfg,     // [2]: Periodic/OneShot; [1:0]: 10: Up, 01: Down, 11: Up/Down
    input   wire [11:0]     pwm0_cfg,
    input   wire [11:0]     pwm1_cfg,
    input   wire            pwm0_inv,
    input   wire            pwm1_inv,
    input   wire [ 7:0]     pwm_dt,
    input   wire [15:0]     pwm_fault_clr,
    input   wire            pwm_dt_en,

    output  wire [31:0]     tmr,
    output  wire            matchx_flag,
    output  wire            matchy_flag,
    output  wire            timeout_flag,

    input   wire            pwm_fault,
    output  wire            pwm0,
    output  wire            pwm1
);
  reg [PRW-1:0] pr;
  wire tick = (pr == {PRW{1'b0}});

  reg [31:0] tmr_reg;
  reg        count_down;
  reg        running;

  wire start_pulse;
  ef_util_ped start_detector (
      .clk(clk),
      .in(tmr_en),
      .out(start_pulse)
  );

  assign tmr = tmr_reg;
  assign matchx_flag = (tmr_reg == cmpx);
  assign matchy_flag = (tmr_reg == cmpy);
  assign timeout_flag = count_down ? (tmr_reg == 32'd0) :
                                      (tmr_reg == tmr_reload);

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
      pr <= {{(PRW-1){1'b0}}, 1'b1};
    else if (!tmr_en)
      pr <= prescaler;
    else if (pr == {PRW{1'b0}})
      pr <= prescaler;
    else
      pr <= pr - {{(PRW-1){1'b0}}, 1'b1};
  end

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      tmr_reg   <= 32'd0;
      count_down <= 1'b0;
      running   <= 1'b0;
    end else begin
      if (start_pulse) begin
        if (tmr_cfg[1:0] == 2'b01) begin
          tmr_reg <= tmr_reload;
          count_down <= 1'b1;
        end else begin
          tmr_reg <= 32'd0;
          count_down <= 1'b0;
        end
        running <= 1'b1;
      end else begin
        if (tick) begin
          case (tmr_cfg[1:0])
            2'b11: begin
              if (!count_down && (tmr_reg == (tmr_reload - 32'd1)))
                count_down <= 1'b1;
              else if (count_down && (tmr_reg == 32'd1))
                count_down <= 1'b0;
            end
            2'b01: count_down <= 1'b1;
            default: count_down <= 1'b0;
          endcase

          if (tmr_en && running) begin
            if (tmr_start && (tmr_cfg[1:0] == 2'b01)) begin
              tmr_reg <= tmr_reload;
            end else if (tmr_start &&
                         ((tmr_cfg[1:0] == 2'b10) ||
                          (tmr_cfg[1:0] == 2'b11))) begin
              tmr_reg <= 32'd0;
            end else begin
              case (tmr_cfg[1:0])
                2'b11: begin
                  if (count_down)
                    tmr_reg <= tmr_reg - 32'd1;
                  else
                    tmr_reg <= tmr_reg + 32'd1;

                  if (!tmr_cfg[2] && count_down && (tmr_reg == 32'd1))
                    running <= 1'b0;
                end

                2'b01: begin
                  if (tmr_reg == 32'd0) begin
                    if (tmr_cfg[2])
                      tmr_reg <= tmr_reload;
                  end else begin
                    tmr_reg <= tmr_reg - 32'd1;
                  end

                  if (!tmr_cfg[2] && (tmr_reg == 32'd1))
                    running <= 1'b0;
