            (tmr_reg == cmpx) &&
            (tmr_reg != 32'd0) &&
            (tmr_reg != cmpy) &&
            (tmr_reg != tmr_reload);
  wire e2 = dir_up &&
            (tmr_reg == cmpy) &&
            (tmr_reg != 32'd0) &&
            (tmr_reg != cmpx) &&
            (tmr_reg != tmr_reload);
  wire e3 = (tmr_reg == tmr_reload) &&
            (tmr_reg != 32'd0) &&
            (tmr_reg != cmpx) &&
            (tmr_reg != cmpy);
  wire e4 = count_down &&
            (tmr_reg == cmpy) &&
            (tmr_reg != 32'd0) &&
            (tmr_reg != cmpx) &&
            (tmr_reg != tmr_reload);
  wire e5 = count_down &&
            (tmr_reg == cmpx) &&
            (tmr_reg != 32'd0) &&
            (tmr_reg != cmpy) &&
