      6'b000010: begin
        pwm0_action = pwm0_cfg[3:2];
        pwm1_action = pwm1_cfg[3:2];
      end
      6'b000100: begin
        pwm0_action = pwm0_cfg[5:4];
        pwm1_action = pwm1_cfg[5:4];
      end
      6'b001000: begin
        pwm0_action = pwm0_cfg[7:6];
        pwm1_action = pwm1_cfg[7:6];
      end
      6'b010000: begin
        pwm0_action = pwm0_cfg[9:8];
        pwm1_action = pwm1_cfg[9:8];
      end
      6'b100000: begin
        pwm0_action = pwm0_cfg[11:10];
        pwm1_action = pwm1_cfg[11:10];
      end
      default: begin
        pwm0_action = 2'b00;
        pwm1_action = 2'b00;
      end
    endcase
