  reg pwm1_state;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      pwm0_state <= 1'b0;
      pwm1_state <= 1'b0;
    end else if (tick && pwm0_en) begin
      if (pwm_fault)
        pwm0_state <= 1'b0;
      else begin
        case (pwm0_action)
          2'b01: pwm0_state <= 1'b0;
          2'b10: pwm0_state <= 1'b1;
          2'b11: pwm0_state <= ~pwm0_state;
          default: pwm0_state <= pwm0_state;
        endcase
      end
    end
  end

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      pwm1_state <= 1'b0;
    end else if (tick && pwm1_en) begin
      if (pwm_fault)
        pwm1_state <= 1'b0;
      else begin
        case (pwm1_action)
          2'b01: pwm1_state <= 1'b0;
          2'b10: pwm1_state <= 1'b1;
          2'b11: pwm1_state <= ~pwm1_state;
          default: pwm1_state <= pwm1_state;
        endcase
      end
    end
  end

  reg [7:0] deadtime_count;
  reg       pwm0_delayed;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      deadtime_count <= 8'd0;
      pwm0_delayed <= 1'b0;
    end else if (tick) begin
      if (deadtime_count == 8'd0)
        deadtime_count <= pwm_dt;
      else
        deadtime_count <= deadtime_count - 8'd1;

      if (deadtime_count == 8'd0)
        pwm0_delayed <= pwm0_state;
    end
  end

  reg pwm0_out_reg;
  reg pwm1_out_reg;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      pwm0_out_reg <= 1'b0;
      pwm1_out_reg <= 1'b0;
    end else if (pwm_dt_en) begin
      pwm0_out_reg <= pwm0_delayed & pwm0_state;
      pwm1_out_reg <= ~pwm0_delayed & ~pwm0_state;
    end else begin
      pwm0_out_reg <= pwm0_state;
      pwm1_out_reg <= pwm1_state;
    end
  end

  reg fault_armed;
  reg fault_latched;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      fault_armed <= 1'b0;
      fault_latched <= 1'b0;
    end else begin
      if (pwm_fault_clr == PWM_FAULT_CLR_C0)
        fault_armed <= 1'b1;
      else if (pwm_fault_clr == PWM_FAULT_CLR_C1)
        fault_armed <= 1'b0;

      if (pwm_fault)
        fault_latched <= 1'b1;
      else if (fault_armed && (pwm_fault_clr == PWM_FAULT_CLR_C1))
        fault_latched <= 1'b0;
    end
  end

  assign pwm0 = (pwm0_out_reg ^ pwm0_inv) &
                ~pwm_fault & ~fault_latched & pwm0_en;
  assign pwm1 = (pwm1_out_reg ^ pwm1_inv) &
                ~pwm_fault & ~fault_latched & pwm1_en;

endmodule

