module edge_detector (
  input      clk,
  input      rst,
  input      sig,
  output reg rise,
  output reg fall,
  output     any_edge
);
  reg prev_sig;

  always @(posedge clk) begin
    if (rst) begin
      prev_sig <= 1'b0;
      rise     <= 1'b0;
      fall     <= 1'b0;
    end else begin
      rise     <= sig & ~prev_sig;
      fall     <= ~sig & prev_sig;
      prev_sig <= sig;
    end
  end

  assign any_edge = rise | fall;
endmodule

