            if (tmr_start && tmr_mode == 2'b01)
                tmr_reg <= tmr_reload;
            else if (tmr_start && (tmr_mode == 2'b10 ||
                                   tmr_mode == 2'b11))
                tmr_reg <= 32'b0;
            else if (tmr_mode == 2'b01 && tmr_start)
                tmr_reg <= tmr_reload;
            else if (tmr_mode != 2'b00 && tmr_start)
                tmr_reg <= 32'b0;
            else if (tmr_mode == 2'b01 && tmr_start)
