            tmr_reg_next = 32'b0;
        else begin
            case (tmr_mode)
                2'b11: begin
                    if (tmr_dir)
                        tmr_reg_next = tmr_reg + 1'b1;
                    else
                        tmr_reg_next = tmr_reg - 1'b1;
                end
                2'b01: begin
                    if (tmr_eq_zero)
                        tmr_reg_next = tmr_periodic ? tmr_reload : tmr_reg;
                    else
                        tmr_reg_next = tmr_reg - 1'b1;
                end
                2'b10: begin
                    if (tmr_eq_reload)
                        tmr_reg_next = tmr_periodic ? 32'b0 : tmr_reg;
                    else
                        tmr_reg_next = tmr_reg + 1'b1;
                end
                default: tmr_reg_next = tmr_reg;
            endcase
