    idx = 0;
    for (i = 0; i < N; i = i + 1)
      if (req[i])
        idx = i;
  end

  assign valid  = |req;
  assign onehot = valid
                ? ({{(N-1){1'b0}}, 1'b1} << idx)
                : {N{1'b0}};
