module traffic_light #(
  parameter GREEN_TIME  = 8,
  parameter MIN_GREEN   = 3,
  parameter YELLOW_TIME = 3,
  parameter RED_TIME    = 6
) (
  input            clk,
  input            rst,
  input            ped,
  output reg [1:0] state,
  output           green,
  output           yellow,
  output           red,
  output           walk
);
  localparam [1:0] GREEN_STATE  = 2'd0;
  localparam [1:0] YELLOW_STATE = 2'd1;
  localparam [1:0] RED_STATE    = 2'd2;

  reg [4:0] phase_count;
  reg       ped_pending;

  assign green  = (state == GREEN_STATE);
  assign yellow = (state == YELLOW_STATE);
  assign red    = (state == RED_STATE);
  assign walk   = red;

  always @(posedge clk) begin
    if (rst) begin
      state       <= GREEN_STATE;
      phase_count <= 5'd0;
      ped_pending <= 1'b0;
    end else begin
      case (state)
        GREEN_STATE: begin
          if ((phase_count >= GREEN_TIME - 1) ||
              (ped_pending && (phase_count >= MIN_GREEN - 1))) begin
            state       <= YELLOW_STATE;
            phase_count <= 5'd0;
          end else begin
            phase_count <= phase_count + 1'b1;
          end

          if (ped)
            ped_pending <= 1'b1;
        end

        YELLOW_STATE: begin
          if (phase_count >= YELLOW_TIME - 1) begin
            state       <= RED_STATE;
            phase_count <= 5'd0;
          end else begin
            phase_count <= phase_count + 1'b1;
          end

          if (ped)
            ped_pending <= 1'b1;
        end

        RED_STATE: begin
          if (phase_count >= RED_TIME - 1) begin
            state       <= GREEN_STATE;
            phase_count <= 5'd0;
          end else begin
            phase_count <= phase_count + 1'b1;
          end

          ped_pending <= 1'b0;
        end

        default: begin
          state       <= GREEN_STATE;
          phase_count <= 5'd0;
          ped_pending <= 1'b0;
        end
      endcase
    end
  end
endmodule

