module intc_sync #(
  parameter N = 8
) (
  input              clk,
  input              rst,
  input      [N-1:0] d,
  output reg [N-1:0] q
);
  reg [N-1:0] meta;

  always @(posedge clk) begin
    if (rst) begin
      meta <= 0;
      q    <= 0;
    end else begin
      meta <= d;
      q    <= meta;
    end
  end
endmodule


module intc_pending #(
  parameter N = 8
) (
  input              clk,
  input              rst,
  input      [N-1:0] src,
  input      [N-1:0] trigger,
  input      [N-1:0] clear_mask,
  input      [N-1:0] force_mask,
  output reg [N-1:0] pending
);
  reg [N-1:0] src_prev;

  wire [N-1:0] rise = src & ~src_prev;
  wire [N-1:0] set  = (trigger & rise) | (~trigger & src) | force_mask;

  always @(posedge clk) begin
    if (rst) begin
      src_prev <= 0;
      pending  <= 0;
    end else begin
      src_prev <= src;
      pending  <= (pending & ~clear_mask) | set;
