  assign irq_id = irq ? best_idx + 1 : {IDW{1'b0}};

  intc_apb_if u_apb (
    .PSEL(PSEL), .PENABLE(PENABLE), .PWRITE(PWRITE), .PADDR(PADDR), .PWDATA(PWDATA),
