    .wr_en(wr_en), .rd_en(rd_en), .addr(addr), .wdata(wdata), .rdata(rdata), .err(err)
  );

  intc_sync #(.N(NUM_SRC)) u_sync (
    .clk(PCLK), .rst(rst), .d(irq_src), .q(src_sync)
