            state   <= S_START;
            tx      <= 1'b0;
            clk_cnt <= 0;
          end
        end
        S_START:
          if (clk_cnt == CLKS_PER_BIT - 1) begin
            clk_cnt <= 0;
            bit_idx <= 0;
            state   <= S_DATA;
            tx      <= shreg[0];
          end else
            clk_cnt <= clk_cnt + 1;
        S_DATA:
