    always @(posedge clk, negedge rst_n)
        if (!rst_n)
            tmr_dir <= 1;
        else if (tmr_en_pulse) begin
            if (tmr_mode == 2'b01)
                tmr_dir <= 0;
            else
                tmr_dir <= 1;
        end
