// From efabless/EF_IP_UTIL hdl/ef_util_lib.v (commit a2b3fb6): the two modules EF_TMR32 needs.
module ef_util_ped (
    input wire clk,
    input wire in,
    output wire out
);
    reg last_in; 
    always @(posedge clk) 
	last_in <= in; 
