    always @(posedge clk, negedge rst_n)
        if (!rst_n)
            pwm0_reg <= 0;
        else if (pwm0_en && tick)
            if (pwm_fault)
                pwm0_reg <= 0;
            else
                pwm0_reg <= pwm0_reg_next;

    always @(posedge clk, negedge rst_n)
        if (!rst_n)
            pwm1_reg <= 0;
        else if (pwm1_en && tick)
            if (pwm_fault)
                pwm1_reg <= 0;
            else
                pwm1_reg <= pwm1_reg_next;

    // Dead time insertion
    reg pwm0_delayed;
    reg [7:0] dly_cntr;
    always @(posedge clk, negedge rst_n)
        if (!rst_n)
            dly_cntr <= 0;
        else if (tick)
            if (dly_cntr == 0)
                dly_cntr <= pwm_dt;
            else
                dly_cntr <= dly_cntr - 1;

    always @(posedge clk, negedge rst_n)
        if (!rst_n)
            pwm0_delayed <= 0;
        else if (tick)
            if (dly_cntr == 0)
                pwm0_delayed <= pwm0_reg;

    reg pwm0_w_dt, pwm1_w_dt;
    always @(posedge clk, negedge rst_n)
        if (!rst_n)
            pwm0_w_dt <= 0;
        else
            pwm0_w_dt <= pwm_dt_en ? (pwm0_delayed & pwm0_reg) : pwm0_reg;

    always @(posedge clk, negedge rst_n)
        if (!rst_n)
            pwm1_w_dt <= 0;
        else
            pwm1_w_dt <= pwm_dt_en ? (~pwm0_delayed & ~pwm0_reg) : pwm1_reg;

    // PWM Fault Handling
    reg fault_clr_reg;
    always @(posedge clk, negedge rst_n)
        if (!rst_n)
            fault_clr_reg <= 0;
        else if (pwm_fault_clr == PWM_FAULT_CLR_C0)
            fault_clr_reg <= 1;
        else if (pwm_fault_clr == PWM_FAULT_CLR_C1)
            fault_clr_reg <= 0;

    always @(posedge clk, negedge rst_n)
        if (!rst_n)
            fault_reg <= 0;
        else if (pwm_fault)
            fault_reg <= 1;
        else if (fault_clr_reg &&
                 (pwm_fault_clr == PWM_FAULT_CLR_C1))
            fault_reg <= 0;

    // Connect the outputs
    assign tmr         = tmr_reg;
    assign pwm0        = (pwm0_w_dt ^ pwm0_inv) & ~fault_reg & ~pwm_fault & pwm0_en;
    assign pwm1        = (pwm1_w_dt ^ pwm1_inv) & ~fault_reg & ~pwm_fault & pwm1_en;
    assign matchx_flag = tmr_eq_cmpx;
    assign matchy_flag = tmr_eq_cmpy;
    assign timeout_flag = tmr_dir ? tmr_eq_reload : tmr_eq_zero;

endmodule

