                    ADDR_IC:           ic_reg           <= PWDATA[9:0];
                    ADDR_GCLK:         gclk_reg         <= PWDATA[0];
                    default: ;
                endcase
            end

            if (ic_reg[0])
                ris_reg[0] <= 1'b0;
            else if (tx_empty)
                ris_reg[0] <= 1'b1;

            if (ic_reg[1])
                ris_reg[1] <= 1'b0;
            else if (rx_full)
                ris_reg[1] <= 1'b1;

            if (ic_reg[2])
                ris_reg[2] <= 1'b0;
            else if (tx_level_below)
                ris_reg[2] <= 1'b1;

            if (ic_reg[3])
                ris_reg[3] <= 1'b0;
            else if (rx_level_above)
                ris_reg[3] <= 1'b1;

            if (ic_reg[4])
                ris_reg[4] <= 1'b0;
            else if (break_flag)
                ris_reg[4] <= 1'b1;

            if (ic_reg[5])
                ris_reg[5] <= 1'b0;
            else if (match_flag)
                ris_reg[5] <= 1'b1;

            if (ic_reg[6])
                ris_reg[6] <= 1'b0;
            else if (frame_error_flag)
                ris_reg[6] <= 1'b1;

            if (ic_reg[7])
                ris_reg[7] <= 1'b0;
            else if (parity_error_flag)
                ris_reg[7] <= 1'b1;

            if (ic_reg[8])
                ris_reg[8] <= 1'b0;
            else if (overrun_flag)
                ris_reg[8] <= 1'b1;

            if (ic_reg[9])
                ris_reg[9] <= 1'b0;
            else if (timeout_flag)
                ris_reg[9] <= 1'b1;
        end
    end

    reg [31:0] prdata_reg;
    always @* begin
        prdata_reg = 32'hDEADBEEF;
        case (addr)
            ADDR_RXDATA:       prdata_reg = {{(32-MDW){1'b0}}, uart_rdata};
            ADDR_PR:           prdata_reg = {16'b0, prescaler_reg};
            ADDR_CTRL:         prdata_reg = {27'b0, ctrl_reg};
            ADDR_CFG:          prdata_reg = {18'b0, cfg_reg};
            ADDR_MATCH:        prdata_reg = {23'b0, match_reg};
            ADDR_RX_LEVEL:     prdata_reg = {28'b0, rx_level[3:0]};
            ADDR_RX_THRESHOLD: prdata_reg = {28'b0, rx_threshold_reg};
            ADDR_RX_FLUSH:     prdata_reg = {31'b0, rx_flush_reg};
            ADDR_TX_LEVEL:     prdata_reg = {28'b0, tx_level[3:0]};
            ADDR_TX_THRESHOLD: prdata_reg = {28'b0, tx_threshold_reg};
            ADDR_TX_FLUSH:     prdata_reg = {31'b0, tx_flush_reg};
            ADDR_IM:           prdata_reg = {22'b0, im_reg};
            ADDR_MIS:          prdata_reg = {22'b0, mis};
            ADDR_RIS:          prdata_reg = {22'b0, ris_reg};
            ADDR_GCLK:         prdata_reg = {31'b0, gclk_reg};
            default: ;
        endcase
    end
    assign PRDATA = prdata_reg;
endmodule

