module ef_util_sync #(parameter NUM_STAGES = 2) (
    input wire clk,
    input wire in,
    output wire out
);

    reg [NUM_STAGES-1:0] sync;

    always @(posedge clk)
        sync <= {sync[NUM_STAGES-2:0], in};

    assign out = sync[NUM_STAGES-1];

endmodule

module ef_util_ticker #(parameter W=8) (
    input   wire            clk, 
    input   wire            rst_n,
    input   wire            en,
    input   wire [W-1:0]    clk_div,
    output  wire            tick
);

    reg [W-1:0] counter;
    wire        counter_is_zero = (counter == 'b0);
    wire        tick_w;
    reg         tick_reg;

    always @(posedge clk, negedge rst_n)
        if(~rst_n)
            counter <=  'b0;
        else if(en) 
            if(counter_is_zero)
                counter <=  clk_div;
            else
                counter <=  counter - 'b1; 

	assign tick_w = (clk_div == 'b0)  ?   1'b1 : counter_is_zero;

    always @(posedge clk or negedge rst_n)
        if(!rst_n)
            tick_reg <= 1'b0;
        else if(en)
            tick_reg <= tick_w;
        else
            tick_reg <= 0;

    assign tick = tick_reg;

endmodule

module ef_util_glitch_filter #(parameter N = 8, CLKDIV = 8'd1) (
    input   wire    clk,
    input   wire    rst_n,
    input   wire    in,
    input   wire    en,
    output  reg     out
);

    reg [N-1:0] shifter;
    wire        tick;

    ef_util_ticker ticker (
        .clk(clk),
        .rst_n(rst_n),
	.en(en),
        .clk_div(CLKDIV),
        .tick(tick)
    );

    always @(posedge clk, negedge rst_n)
        if(!rst_n)
            shifter <= 'b0;
        else if(tick)
            shifter <= {shifter[N-2:0], in};

    wire all_ones   = & shifter;
    wire all_zeros  = ~| shifter;

    always @(posedge clk, negedge rst_n)
        if(!rst_n)
            out <= 1'b0;
        else
            if(all_ones) 
                out <= 1'b1;
            else if(all_zeros) 
                out <= 1'b0;
endmodule

module ef_util_fifo #(parameter DW=8, AW=4)(
    input   wire            clk,
    input   wire            rst_n,
    input   wire            rd,
    input   wire            wr,
    input   wire            flush,
    input   wire [DW-1:0]   wdata,
    output  wire            empty,
    output  wire            full,
    output  wire [DW-1:0]   rdata,
    output  wire [AW-1:0]   level    
);
    localparam DEPTH = (1 << AW);

    reg [DW-1:0] mem [0:DEPTH-1];
    reg [AW-1:0] rd_ptr;
    reg [AW-1:0] wr_ptr;
    reg [AW-1:0] level_reg;
    reg          empty_reg;
    reg          full_reg;

    wire         wr_accept = wr & ~full_reg;
    wire [AW-1:0] rd_ptr_next = rd_ptr + {{(AW-1){1'b0}}, 1'b1};
    wire [AW-1:0] wr_ptr_next = wr_ptr + {{(AW-1){1'b0}}, 1'b1};

    assign empty = empty_reg;
    assign full  = full_reg;
    assign level = level_reg;
    assign rdata = mem[rd_ptr];

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rd_ptr    <= {AW{1'b0}};
            wr_ptr    <= {AW{1'b0}};
            level_reg <= {AW{1'b0}};
            empty_reg <= 1'b1;
            full_reg  <= 1'b0;
        end else if (flush) begin
            rd_ptr    <= {AW{1'b0}};
            wr_ptr    <= {AW{1'b0}};
            level_reg <= {AW{1'b0}};
            empty_reg <= 1'b1;
            full_reg  <= 1'b0;
        end else begin
            if (wr_accept)
                mem[wr_ptr] <= wdata;

            if (wr_accept && rd) begin
                rd_ptr <= rd_ptr_next;
                wr_ptr <= wr_ptr_next;
            end else if (wr_accept) begin
                wr_ptr    <= wr_ptr_next;
                level_reg <= level_reg + {{(AW-1){1'b0}}, 1'b1};
                empty_reg <= 1'b0;
                full_reg  <= (wr_ptr_next == rd_ptr);
            end else if (rd && !empty_reg) begin
                rd_ptr    <= rd_ptr_next;
                level_reg <= level_reg - {{(AW-1){1'b0}}, 1'b1};
                empty_reg <= (rd_ptr_next == wr_ptr);
                full_reg  <= 1'b0;
            end
        end
    end
endmodule

