// APB interrupt controller: NUM_SRC sources, PRIO_BITS of priority each,
// claim/complete handshake. See spec.md for the full register map.

module intc_apb_if (
  input         PSEL,
  input         PENABLE,
  input         PWRITE,
  input  [7:0]  PADDR,
  input  [31:0] PWDATA,
  output [31:0] PRDATA,
  output        PREADY,
  output        PSLVERR,
  output        wr_en,
  output        rd_en,
  output [7:0]  addr,
  output [31:0] wdata,
  input  [31:0] rdata,
  input         err
);
  assign PREADY = 1'b1;

  assign wr_en = PSEL && PENABLE && PWRITE;
  assign rd_en = PSEL && PENABLE && !PWRITE;

  assign addr  = PADDR;
  assign wdata = PWDATA;

  assign PRDATA  = (rd_en && !err) ? rdata : 32'b0;
  assign PSLVERR = ((wr_en || rd_en) && err);
endmodule


module intc_sync #(
  parameter N = 8
) (
  input              clk,
  input              rst,
  input      [N-1:0] d,
  output reg [N-1:0] q
);
  reg [N-1:0] meta;

  always @(posedge clk) begin
    if (rst) begin
      meta <= 0;
      q    <= 0;
    end else begin
      meta <= d;
      q    <= meta;
    end
  end
endmodule


module intc_pending #(
  parameter N = 8
) (
  input              clk,
  input              rst,
  input      [N-1:0] src,
  input      [N-1:0] trigger,
  input      [N-1:0] clear_mask,
  input      [N-1:0] force_mask,
  output reg [N-1:0] pending
);
  reg [N-1:0] src_prev;

  wire [N-1:0] rise = src & ~src_prev;
  wire [N-1:0] set  = (trigger & rise) | (~trigger & src) | force_mask;

  always @(posedge clk) begin
    if (rst) begin
      src_prev <= 0;
      pending  <= 0;
    end else begin
      src_prev <= src;
      pending  <= (pending & ~clear_mask) | set;
    end
  end
endmodule


module intc_prio_select #(
  parameter N         = 8,
  parameter PRIO_BITS = 3
) (
  input      [N-1:0]           eligible,
  input      [N*PRIO_BITS-1:0] prio_flat,
  output reg                   best_valid,
  output reg [$clog2(N)-1:0]   best_idx,
  output reg [PRIO_BITS-1:0]   best_prio
);
  integer k;

  // Highest priority wins; strict > keeps the lowest index on a tie and
  // never selects a priority-0 source.
  always @(*) begin
    best_valid = 1'b0;
    best_idx   = 0;
    best_prio  = 0;
    for (k = 0; k < N; k = k + 1)
      if (eligible[k] && prio_flat[k*PRIO_BITS +: PRIO_BITS] > best_prio) begin
        best_valid = 1'b1;
        best_idx   = k;
        best_prio  = prio_flat[k*PRIO_BITS +: PRIO_BITS];
      end
  end
endmodule


module intc_regs #(
  parameter NUM_SRC   = 8,
  parameter PRIO_BITS = 3
) (
  input                              clk,
  input                              rst,
  input                              wr_en,
  input                              rd_en,
  input      [7:0]                   addr,
  input      [31:0]                  wdata,
  output reg [31:0]                  rdata,
  output                             err,
  input      [NUM_SRC-1:0]           pending,
  input                              irq,
  input      [$clog2(NUM_SRC+1)-1:0] irq_id,
  output reg                         gen,
  output reg [NUM_SRC-1:0]           enable,
  output reg [NUM_SRC-1:0]           trigger,
  output reg [NUM_SRC-1:0]           in_service,
  output reg [PRIO_BITS-1:0]         threshold,
  output reg [NUM_SRC*PRIO_BITS-1:0] prio_flat,
  output     [NUM_SRC-1:0]           clear_mask,
  output     [NUM_SRC-1:0]           force_mask
);
  localparam PRIO_WORDS = (NUM_SRC + 7) / 8;

  reg addr_valid;
  reg addr_readonly;
  reg [NUM_SRC-1:0] clear_mask_int;
  reg [NUM_SRC-1:0] force_mask_int;

  integer ri;
  integer wi;
  integer mi;

  // Decode all implemented addresses and identify the read-only registers.
  always @(*) begin
    addr_valid    = 1'b0;
    addr_readonly = 1'b0;

    case (addr)
      8'h00, // CTRL
      8'h04, // ENABLE
      8'h08, // TRIGGER
      8'h0C, // PENDING
      8'h10, // FORCE
      8'h14, // THRESHOLD
      8'h18: // CLAIM
        addr_valid = 1'b1;

      8'h1C, // INSERVICE
      8'h20, // STATUS
      8'h24: begin // ID
        addr_valid    = 1'b1;
        addr_readonly = 1'b1;
      end

      default: begin
        if ((addr >= 8'h40) &&
            (addr < (8'h40 + (PRIO_WORDS * 4)))) begin
          addr_valid = 1'b1;
        end
      end
    endcase

    if (addr[1:0] != 2'b00)
      addr_valid = 1'b0;
  end

  assign err = !addr_valid || (wr_en && addr_readonly);

  // Generate the pending clear and force masks for the pending-bit logic.
  always @(*) begin
    clear_mask_int = {NUM_SRC{1'b0}};
    force_mask_int = {NUM_SRC{1'b0}};

    if (wr_en && !err) begin
      if (addr == 8'h0C)
        clear_mask_int = wdata[NUM_SRC-1:0];
      else if (addr == 8'h10)
        force_mask_int = wdata[NUM_SRC-1:0];
    end

    if (rd_en && !err && (addr == 8'h18) && irq) begin
      for (mi = 0; mi < NUM_SRC; mi = mi + 1)
        if (irq_id == (mi + 1))
          clear_mask_int[mi] = 1'b1;
    end
  end

  assign clear_mask = clear_mask_int;
  assign force_mask = force_mask_int;

  // Register read mux. Unimplemented bits and write-only register reads are zero.
  always @(*) begin
    rdata = 32'b0;

    case (addr)
      8'h00: rdata[0] = gen;
      8'h04: rdata[NUM_SRC-1:0] = enable;
      8'h08: rdata[NUM_SRC-1:0] = trigger;
      8'h0C: rdata[NUM_SRC-1:0] = pending;
      8'h10: rdata = 32'b0;
      8'h14: rdata[PRIO_BITS-1:0] = threshold;
      8'h18: rdata = irq ? irq_id : 32'b0;
      8'h1C: rdata[NUM_SRC-1:0] = in_service;
      8'h20: begin
        rdata[0] = irq;
        rdata[8 +: $clog2(NUM_SRC+1)] = irq_id;
      end
      8'h24: rdata = 32'h1C0D0000 + (PRIO_BITS << 8) + NUM_SRC;
      default: begin
        if ((addr >= 8'h40) &&
            (addr < (8'h40 + (PRIO_WORDS * 4))) &&
            (addr[1:0] == 2'b00)) begin
          for (ri = 0; ri < NUM_SRC; ri = ri + 1)
            if (addr == (8'h40 + ((ri / 8) * 4)))
              rdata[(ri % 8) * 4 +: PRIO_BITS] =
                  prio_flat[ri * PRIO_BITS +: PRIO_BITS];
        end
      end
    endcase
  end

  // Register writes and claim/complete state changes.
  always @(posedge clk) begin
    if (rst) begin
      gen        <= 1'b0;
      enable     <= {NUM_SRC{1'b0}};
      trigger    <= {NUM_SRC{1'b0}};
      in_service <= {NUM_SRC{1'b0}};
      threshold  <= {PRIO_BITS{1'b0}};
      prio_flat  <= {NUM_SRC*PRIO_BITS{1'b0}};
    end else begin
      if (wr_en && !err) begin
