    always @(posedge clk, negedge rst_n)
        if (!rst_n)
            tmr_reg <= 0;
        else if (tmr_en_pulse) begin
            if (tmr_mode == 2'b01)
                tmr_reg <= tmr_reload;
            else
                tmr_reg <= 0;
