`timescale          1ns/1ps
`default_nettype    none                                                   

module EF_TMR32 #(parameter PRW = 16,
                                PWM_FAULT_CLR_C0 = 16'hA539,
                                PWM_FAULT_CLR_C1 = 16'hA953 
)
(
    input   wire            clk,
    input   wire            rst_n,

    input   wire            tmr_en,
    input   wire            tmr_start,
    input   wire            pwm0_en,
    input   wire            pwm1_en,
    input   wire [31:0]     tmr_reload,
    input   wire [31:0]     cmpx,
    input   wire [31:0]     cmpy,
    input   wire [PRW-1:0]  prescaler,
    input   wire [ 2:0]     tmr_cfg,     // [2]: Periodic/OneShot; [1:0]: 10: Up, 01: Down, 11: Up/Down
    input   wire [11:0]     pwm0_cfg,
    input   wire [11:0]     pwm1_cfg,
    input   wire            pwm0_inv,
    input   wire            pwm1_inv,
    input   wire [ 7:0]     pwm_dt,
    input   wire [15:0]     pwm_fault_clr,
    input   wire            pwm_dt_en,

    output  wire [31:0]     tmr,
    output  wire            matchx_flag,
    output  wire            matchy_flag,
    output  wire            timeout_flag,

    input   wire            pwm_fault,
    output  wire            pwm0,
    output  wire            pwm1
);
  reg [PRW-1:0] pr;
  reg [31:0] tmr_reg;
  reg direction_down;
  reg running;

  wire start_pulse;
  wire tick;

  ef_util_ped u_te_ped (
      .clk(clk),
      .in(tmr_en),
      .out(start_pulse)
  );

  assign tick = (pr == {PRW{1'b0}});
  assign tmr = tmr_reg;
  assign matchx_flag = (tmr_reg == cmpx);
  assign matchy_flag = (tmr_reg == cmpy);
  assign timeout_flag = direction_down ?
                        (tmr_reg == 32'b0) : (tmr_reg == tmr_reload);

  // Prescaler counter.
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
      pr <= {{(PRW-1){1'b0}}, 1'b1};
    else if (!tmr_en)
      pr <= prescaler;
    else if (pr == {PRW{1'b0}})
      pr <= prescaler;
    else
      pr <= pr - {{(PRW-1){1'b0}}, 1'b1};
  end

  // Timer value and running state.
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      tmr_reg <= 32'b0;
      running <= 1'b0;
    end else if (start_pulse) begin
      tmr_reg <= (tmr_cfg[1:0] == 2'b01) ? tmr_reload : 32'b0;
      running <= 1'b1;
    end else begin
      if (tmr_en && tick && running) begin
        if (tmr_start && (tmr_cfg[1:0] == 2'b01)) begin
          tmr_reg <= tmr_reload;
        end else if (tmr_start &&
                     ((tmr_cfg[1:0] == 2'b10) ||
                      (tmr_cfg[1:0] == 2'b11))) begin
          tmr_reg <= 32'b0;
        end else begin
          case (tmr_cfg[1:0])
            2'b11: begin
              if (direction_down)
                tmr_reg <= tmr_reg - 32'd1;
              else
                tmr_reg <= tmr_reg + 32'd1;
            end

            2'b01: begin
              if (tmr_reg == 32'b0) begin
                if (tmr_cfg[2])
                  tmr_reg <= tmr_reload;
                else
                  tmr_reg <= tmr_reg;
              end else begin
                tmr_reg <= tmr_reg - 32'd1;
              end
            end

            2'b10: begin
              if (tmr_reg == tmr_reload) begin
                if (tmr_cfg[2])
                  tmr_reg <= 32'b0;
                else
                  tmr_reg <= tmr_reg;
              end else begin
                tmr_reg <= tmr_reg + 32'd1;
              end
            end

            default: tmr_reg <= tmr_reg;
          endcase
        end
      end

      if (tmr_en && tick && running && !tmr_cfg[2] &&
          tmr_cfg[1:0] != 2'b00 && tmr_reg == 32'd1 &&
          direction_down)
        running <= 1'b0;
    end
  end

  // Counting direction. This is updated on every prescaler tick, even
  // when the timer itself is disabled.
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
      direction_down <= 1'b0;
    else if (start_pulse)
      direction_down <= (tmr_cfg[1:0] == 2'b01);
    else if (tick) begin
      case (tmr_cfg[1:0])
        2'b11: begin
          if (!direction_down &&
              (tmr_reg == (tmr_reload - 32'd1)))
            direction_down <= 1'b1;
          else if (direction_down && (tmr_reg == 32'd1))
