        RIS_REG[0] <= 1'b0;
      else if (timeout_flag)
        RIS_REG[0] <= 1'b1;

      if (IC_REG[1])
        RIS_REG[1] <= 1'b0;
      else if (matchx_flag)
        RIS_REG[1] <= 1'b1;

      if (IC_REG[2])
        RIS_REG[2] <= 1'b0;
      else if (matchy_flag)
        RIS_REG[2] <= 1'b1;
    end
  end

  assign IRQ = |MIS_REG;

  EF_TMR32 #(
      .PRW(PRW)
  ) instance_to_wrap (
      .clk(clk),
      .rst_n(rst_n),
      .tmr_en(tmr_en),
      .tmr_start(tmr_start),
      .pwm0_en(pwm0_en),
      .pwm1_en(pwm1_en),
      .tmr_reload(tmr_reload),
      .cmpx(cmpx),
