            state <= S_GREEN;
            timer <= 0;
          end else
            timer <= timer + 1;
        default: begin
          state <= S_GREEN;
          timer <= 0;
        end
      endcase
    end
  end

  assign green  = (state == S_GREEN);
  assign yellow = (state == S_YELLOW);
  assign red    = (state == S_RED);
  assign walk   = red;
