module uart_tx #(
  parameter CLKS_PER_BIT = 4
) (
  input       clk,
  input       rst,
  input       start,
  input [7:0] data,
  output reg  tx,
  output      busy,
  output reg  done
);
  localparam IDLE = 1'b0;
  localparam SEND = 1'b1;

  reg        state;
  reg [31:0] clk_count;
  reg [3:0]  bit_index;
  reg [7:0]  data_reg;

  assign busy = (state == SEND);

  always @(posedge clk) begin
    if (rst) begin
      state     <= IDLE;
      clk_count <= 32'd0;
      bit_index <= 4'd0;
      data_reg  <= 8'd0;
      tx        <= 1'b1;
      done      <= 1'b0;
    end else begin
      done <= 1'b0;

      case (state)
        IDLE: begin
          tx        <= 1'b1;
          clk_count <= 32'd0;
          bit_index <= 4'd0;

          if (start) begin
            data_reg  <= data;
            state     <= SEND;
            tx        <= 1'b0;
            clk_count <= 32'd0;
          end
        end

        SEND: begin
          if (clk_count == CLKS_PER_BIT - 1) begin
            clk_count <= 32'd0;

            if (bit_index == 4'd9) begin
              state <= IDLE;
              tx    <= 1'b1;
              done  <= 1'b1;
            end else begin
              bit_index <= bit_index + 1'b1;

              if (bit_index < 4'd8) begin
                tx       <= data_reg[0];
                data_reg <= {1'b0, data_reg[7:1]};
              end else begin
                tx <= 1'b1;
              end
            end
          end else begin
            clk_count <= clk_count + 1'b1;
          end
        end

        default: begin
          state <= IDLE;
          tx    <= 1'b1;
        end
      endcase
    end
  end
endmodule

