module ef_util_fifo #(parameter DW=8, AW=4)(
    input   wire            clk,
    input   wire            rst_n,
    input   wire            rd,
    input   wire            wr,
    input   wire            flush,
    input   wire [DW-1:0]   wdata,
    output  wire            empty,
    output  wire            full,
    output  wire [DW-1:0]   rdata,
    output  wire [AW-1:0]   level    
);
    localparam DEPTH = (1 << AW);

    reg [DW-1:0] mem [0:DEPTH-1];
    reg [AW-1:0] read_ptr;
    reg [AW-1:0] write_ptr;
    reg [AW:0]   count;

    wire accepted_write = wr && !full;

    assign empty = (count == 0);
    assign full  = (count == DEPTH);
    assign level = count[AW-1:0];
    assign rdata = mem[read_ptr];

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            read_ptr  <= {AW{1'b0}};
            write_ptr <= {AW{1'b0}};
            count     <= {(AW+1){1'b0}};
        end else if (flush) begin
            read_ptr  <= {AW{1'b0}};
            write_ptr <= {AW{1'b0}};
            count     <= {(AW+1){1'b0}};
        end else begin
            if (accepted_write) begin
                mem[write_ptr] <= wdata;
                write_ptr <= write_ptr + 1'b1;
            end

            if (accepted_write && rd) begin
                // A raw read accompanies every accepted write, including
                // when empty: advance both pointers without changing count.
                read_ptr <= read_ptr + 1'b1;
            end else if (rd && !empty) begin
                read_ptr <= read_ptr + 1'b1;
            end

            if (accepted_write && !rd)
                count <= count + 1'b1;
            else if (!accepted_write && rd && !empty)
                count <= count - 1'b1;
        end
    end
