  output        rd_en,
  output [7:0]  addr,
  output [31:0] wdata,
  input  [31:0] rdata,
  input         err
);
  wire access = PSEL && PENABLE;

  assign wr_en   = access && PWRITE;
  assign rd_en   = access && !PWRITE;
  assign addr    = PADDR;
  assign wdata   = PWDATA;
