// APB interrupt controller: NUM_SRC sources, PRIO_BITS of priority each,
// claim/complete handshake. See spec.md for the full register map.

module intc_apb_if (
  input         PSEL,
  input         PENABLE,
  input         PWRITE,
  input  [7:0]  PADDR,
  input  [31:0] PWDATA,
  output [31:0] PRDATA,
  output        PREADY,
  output        PSLVERR,
  output        wr_en,
  output        rd_en,
  output [7:0]  addr,
  output [31:0] wdata,
  input  [31:0] rdata,
  input         err
);
  wire access = PSEL && PENABLE;

  assign wr_en   = access && PWRITE;
  assign rd_en   = access && !PWRITE;
  assign addr    = PADDR;
  assign wdata   = PWDATA;
  assign PREADY  = 1'b1;
  assign PSLVERR = access && err;
  assign PRDATA  = (rd_en && !err) ? rdata : 32'b0;
endmodule


module intc_sync #(
  parameter N = 8
) (
  input              clk,
  input              rst,
  input      [N-1:0] d,
  output reg [N-1:0] q
);
  reg [N-1:0] meta;

  always @(posedge clk) begin
    if (rst) begin
      meta <= 0;
      q    <= 0;
    end else begin
      meta <= d;
      q    <= meta;
    end
  end
endmodule


module intc_pending #(
  parameter N = 8
) (
  input              clk,
  input              rst,
  input      [N-1:0] src,
  input      [N-1:0] trigger,
  input      [N-1:0] clear_mask,
  input      [N-1:0] force_mask,
  output reg [N-1:0] pending
);
  reg [N-1:0] src_prev;

  wire [N-1:0] rise = src & ~src_prev;
  wire [N-1:0] set  = (trigger & rise) | (~trigger & src) | force_mask;

  always @(posedge clk) begin
    if (rst) begin
      src_prev <= 0;
      pending  <= 0;
    end else begin
      src_prev <= src;
      pending  <= (pending & ~clear_mask) | set;
    end
  end
endmodule


module intc_prio_select #(
  parameter N         = 8,
  parameter PRIO_BITS = 3
) (
  input      [N-1:0]           eligible,
  input      [N*PRIO_BITS-1:0] prio_flat,
  output reg                   best_valid,
  output reg [$clog2(N)-1:0]   best_idx,
  output reg [PRIO_BITS-1:0]   best_prio
);
  integer k;

  // Highest priority wins; strict > keeps the lowest index on a tie and
  // never selects a priority-0 source.
  always @(*) begin
    best_valid = 1'b0;
    best_idx   = 0;
    best_prio  = 0;
    for (k = 0; k < N; k = k + 1)
      if (eligible[k] && prio_flat[k*PRIO_BITS +: PRIO_BITS] > best_prio) begin
        best_valid = 1'b1;
        best_idx   = k;
        best_prio  = prio_flat[k*PRIO_BITS +: PRIO_BITS];
      end
  end
endmodule


module intc_regs #(
  parameter NUM_SRC   = 8,
  parameter PRIO_BITS = 3
) (
  input                              clk,
  input                              rst,
  input                              wr_en,
  input                              rd_en,
  input      [7:0]                   addr,
  input      [31:0]                  wdata,
  output reg [31:0]                  rdata,
  output                             err,
  input      [NUM_SRC-1:0]           pending,
  input                              irq,
  input      [$clog2(NUM_SRC+1)-1:0] irq_id,
  output reg                         gen,
  output reg [NUM_SRC-1:0]           enable,
  output reg [NUM_SRC-1:0]           trigger,
  output reg [NUM_SRC-1:0]           in_service,
  output reg [PRIO_BITS-1:0]         threshold,
  output reg [NUM_SRC*PRIO_BITS-1:0] prio_flat,
  output     [NUM_SRC-1:0]           clear_mask,
  output     [NUM_SRC-1:0]           force_mask
);
  localparam PRIO_WORDS = (NUM_SRC + 7) / 8;
  localparam [31:0] ID_VALUE =
      32'h1C0D0000 + (PRIO_BITS << 8) + NUM_SRC;

  reg addr_valid;
  reg write_ro;
  reg [NUM_SRC-1:0] clear_mask_r;
  reg [NUM_SRC-1:0] force_mask_r;

  integer dec_k;
  integer rd_i;
  integer mask_i;
  integer seq_i;

  assign err        = !addr_valid || (wr_en && write_ro);
  assign clear_mask = clear_mask_r;
  assign force_mask = force_mask_r;

  // Address validation and read-only register detection.
  always @(*) begin
    addr_valid = 1'b1;
    write_ro   = 1'b0;

    if (addr[1:0] != 2'b00) begin
      addr_valid = 1'b0;
    end else begin
      case (addr)
        8'h00, 8'h04, 8'h08, 8'h0C, 8'h10, 8'h14, 8'h18:
          addr_valid = 1'b1;
        8'h1C, 8'h20, 8'h24: begin
          addr_valid = 1'b1;
          write_ro   = 1'b1;
        end
        default: begin
          addr_valid = 1'b0;
          for (dec_k = 0; dec_k < PRIO_WORDS; dec_k = dec_k + 1)
            if (addr == (8'h40 + (dec_k * 4)))
              addr_valid = 1'b1;
        end
      endcase
    end
  end

  // Register read mux. The APB interface masks this data outside valid
  // access-cycle reads and whenever err is asserted.
  always @(*) begin
    rdata = 32'b0;

    case (addr)
      8'h00: rdata[0] = gen;
      8'h04: rdata[NUM_SRC-1:0] = enable;
      8'h08: rdata[NUM_SRC-1:0] = trigger;
      8'h0C: rdata[NUM_SRC-1:0] = pending;
      8'h10: rdata = 32'b0;
      8'h14: rdata[PRIO_BITS-1:0] = threshold;
      8'h18: rdata = irq_id;
      8'h1C: rdata[NUM_SRC-1:0] = in_service;
      8'h20: begin
        rdata[0]      = irq;
        rdata[15:8]   = irq_id;
      end
      8'h24: rdata = ID_VALUE;
      default: begin
        for (rd_i = 0; rd_i < NUM_SRC; rd_i = rd_i + 1)
          if (addr == (8'h40 + ((rd_i / 8) * 4)))
            rdata[4*(rd_i % 8) +: PRIO_BITS] =
                prio_flat[rd_i*PRIO_BITS +: PRIO_BITS];
      end
    endcase
  end

  // Pending clear and software-force masks for this access cycle.
  always @(*) begin
    clear_mask_r = {NUM_SRC{1'b0}};
    force_mask_r = {NUM_SRC{1'b0}};

    if (wr_en && !err && addr == 8'h0C)
      clear_mask_r = wdata[NUM_SRC-1:0];

    if (wr_en && !err && addr == 8'h10)
      force_mask_r = wdata[NUM_SRC-1:0];

    if (rd_en && !err && addr == 8'h18 && irq) begin
      for (mask_i = 0; mask_i < NUM_SRC; mask_i = mask_i + 1)
        if (irq_id == (mask_i + 1))
          clear_mask_r[mask_i] = 1'b1;
    end
  end

  // Register state and claim/complete side effects.
  always @(posedge clk) begin
    if (rst) begin
      gen        <= 1'b0;
      enable     <= {NUM_SRC{1'b0}};
      trigger    <= {NUM_SRC{1'b0}};
      in_service <= {NUM_SRC{1'b0}};
      threshold  <= {PRIO_BITS{1'b0}};
      prio_flat  <= {NUM_SRC*PRIO_BITS{1'b0}};
    end else begin
      if (wr_en && !err) begin
        case (addr)
          8'h00: gen       <= wdata[0];
          8'h04: enable    <= wdata[NUM_SRC-1:0];
          8'h08: trigger   <= wdata[NUM_SRC-1:0];
          8'h14: threshold <= wdata[PRIO_BITS-1:0];
          default: begin
          end
        endcase

        if (addr == 8'h18) begin
          for (seq_i = 0; seq_i < NUM_SRC; seq_i = seq_i + 1)
            if (wdata == (seq_i + 1))
              in_service[seq_i] <= 1'b0;
        end

        for (seq_i = 0; seq_i < NUM_SRC; seq_i = seq_i + 1)
          if (addr == (8'h40 + ((seq_i / 8) * 4)))
            prio_flat[seq_i*PRIO_BITS +: PRIO_BITS] <=
                wdata[4*(seq_i % 8) +: PRIO_BITS];
      end

      if (rd_en && !err && addr == 8'h18 && irq) begin
        for (seq_i = 0; seq_i < NUM_SRC; seq_i = seq_i + 1)
          if (irq_id == (seq_i + 1))
            in_service[seq_i] <= 1'b1;
      end
    end
  end
endmodule


module apb_intc #(
  parameter NUM_SRC   = 8,
  parameter PRIO_BITS = 3
) (
  input                              PCLK,
  input                              PRESETn,
  input                              PSEL,
  input                              PENABLE,
  input                              PWRITE,
  input  [7:0]                       PADDR,
  input  [31:0]                      PWDATA,
  output [31:0]                      PRDATA,
  output                             PREADY,
  output                             PSLVERR,
  input  [NUM_SRC-1:0]               irq_src,
  output                             irq,
  output [$clog2(NUM_SRC+1)-1:0]     irq_id
);
  localparam IDW = $clog2(NUM_SRC + 1);

  wire                     rst = !PRESETn;
  wire                     wr_en, rd_en, err;
  wire [7:0]               addr;
  wire [31:0]              wdata, rdata;
  wire                     gen;
  wire [NUM_SRC-1:0]       enable, trigger, in_service, pending, src_sync, clear_mask, force_mask;
  wire [PRIO_BITS-1:0]     threshold, best_prio;
  wire [NUM_SRC*PRIO_BITS-1:0] prio_flat;
  wire                     best_valid;
  wire [$clog2(NUM_SRC)-1:0] best_idx;

  wire eligible_any = best_valid && gen && (best_prio > threshold);
  wire [NUM_SRC-1:0] eligible = pending & enable & ~in_service;

  assign irq    = eligible_any;
  assign irq_id = irq ? best_idx + 1 : {IDW{1'b0}};

  intc_apb_if u_apb (
    .PSEL(PSEL), .PENABLE(PENABLE), .PWRITE(PWRITE), .PADDR(PADDR), .PWDATA(PWDATA),
    .PRDATA(PRDATA), .PREADY(PREADY), .PSLVERR(PSLVERR),
    .wr_en(wr_en), .rd_en(rd_en), .addr(addr), .wdata(wdata), .rdata(rdata), .err(err)
  );

  intc_sync #(.N(NUM_SRC)) u_sync (
    .clk(PCLK), .rst(rst), .d(irq_src), .q(src_sync)
  );

  intc_pending #(.N(NUM_SRC)) u_pending (
    .clk(PCLK), .rst(rst), .src(src_sync), .trigger(trigger),
    .clear_mask(clear_mask), .force_mask(force_mask), .pending(pending)
  );

  intc_prio_select #(.N(NUM_SRC), .PRIO_BITS(PRIO_BITS)) u_select (
    .eligible(eligible), .prio_flat(prio_flat),
    .best_valid(best_valid), .best_idx(best_idx), .best_prio(best_prio)
  );

  intc_regs #(.NUM_SRC(NUM_SRC), .PRIO_BITS(PRIO_BITS)) u_regs (
    .clk(PCLK), .rst(rst), .wr_en(wr_en), .rd_en(rd_en), .addr(addr), .wdata(wdata),
    .rdata(rdata), .err(err), .pending(pending), .irq(irq), .irq_id(irq_id),
    .gen(gen), .enable(enable), .trigger(trigger), .in_service(in_service),
    .threshold(threshold), .prio_flat(prio_flat),
    .clear_mask(clear_mask), .force_mask(force_mask)
  );
endmodule
