module shift_reg #(
  parameter WIDTH = 8
) (
  input                  clk,
  input                  rst,
  input                  load,
  input      [WIDTH-1:0] din,
  input                  shift_en,
  input                  dir,
  input                  sin,
  output reg [WIDTH-1:0] q,
  output                 sout
);
