            tmr_run <= 1'b1;
        else if (!tmr_periodic && tick && tmr_mode[0] &&
                 tmr_eq_one && !tmr_dir)
            tmr_run <= 1'b0;

    // The timer
    always @(posedge clk, negedge rst_n)
        if (!rst_n)
            tmr_reg <= 32'b0;
        else if (tmr_en) begin
            if (tmr_start_pulse) begin
                if (tmr_mode == 2'b01)
                    tmr_reg <= tmr_reload;
                else
                    tmr_reg <= 32'b0;
            end else if (tick && tmr_run) begin
                if (tmr_start && tmr_mode == 2'b01)
                    tmr_reg <= tmr_reload;
                else if (tmr_start &&
                         (tmr_mode == 2'b10 || tmr_mode == 2'b11))
                    tmr_reg <= 32'b0;
                else if (tmr_mode == 2'b11) begin
                    if (tmr_dir)
                        tmr_reg <= tmr_reg + 1'b1;
                    else
                        tmr_reg <= tmr_reg - 1'b1;
                end else if (tmr_mode == 2'b01) begin
                    if (tmr_eq_zero)
                        tmr_reg <= tmr_periodic ? tmr_reload : tmr_reg;
                    else
                        tmr_reg <= tmr_reg - 1'b1;
                end else if (tmr_mode == 2'b10) begin
                    if (tmr_eq_reload)
                        tmr_reg <= tmr_periodic ? 32'b0 : tmr_reg;
                    else
                        tmr_reg <= tmr_reg + 1'b1;
                end
            end
        end

