        if (!rst_n)
            tmr_dir <= 1'b1;
        else if (tmr_start_pulse)
            tmr_dir <= (tmr_mode == 2'b01) ? 1'b0 : 1'b1;
        else if (tick) begin
            if (tmr_mode == 2'b11) begin
                if (tmr_eq_one && !tmr_dir)
                    tmr_dir <= 1'b1;
