                    tmr_dir <= 1'b0;
            end else if (tmr_mode == 2'b10)
                tmr_dir <= 1'b1;
            else if (tmr_mode == 2'b01)
                tmr_dir <= 1'b0;
            else
                tmr_dir <= 1'b1;
        end

