  input            clk,
  input            rst,
  input            ped,
  output reg [1:0] state,
  output           green,
  output           yellow,
  output           red,
  output           walk
);
  localparam S_GREEN  = 2'd0;
  localparam S_YELLOW = 2'd1;
  localparam S_RED    = 2'd2;

  reg [3:0] timer;
  reg       ped_pending;

  wire green_done = (timer == GREEN_TIME - 1) || (ped_pending && timer >= MIN_GREEN - 1);

  always @(posedge clk) begin
    if (rst) begin
      state       <= S_GREEN;
      timer       <= 0;
      ped_pending <= 1'b0;
    end else begin
      if (state == S_RED)
        ped_pending <= 1'b0;
