    output  wire            matchx_flag,
    output  wire            matchy_flag,
    output  wire            timeout_flag,

    input   wire            pwm_fault,
    output  wire            pwm0,
    output  wire            pwm1
);

    wire [1:0]      tmr_mode        = tmr_cfg[1:0];
    wire            tmr_periodic    = tmr_cfg[2];

    reg [31:0]      tmr_reg;
    reg [PRW-1:0]   pr_reg;

    wire            tmr_clr;

    wire            tmr_en_pulse = tmr_clr;
    reg             tmr_run;

    reg             fault_reg;

    ef_util_ped TMREN_PE (
        .clk(clk),
        .in(tmr_en),
        .out(tmr_clr)
    );

    wire tick = (pr_reg == 0);
    always @(posedge clk, negedge rst_n)
        if (!rst_n)
            pr_reg <= 1;
        else if (tmr_en)
            if (tick)
                pr_reg <= prescaler;
            else
                pr_reg <= pr_reg - 1'b1;
        else
            pr_reg <= prescaler;

    reg         tmr_dir;        // 1: Up, 0: Down
    wire        tmr_eq_reload       = (tmr == tmr_reload);
    wire        tmr_eq_zero         = (tmr == 0);
    wire        tmr_eq_reload_m_1   = (tmr == (tmr_reload - 32'd1));
    wire        tmr_eq_one          = (tmr == 1);
    wire        tmr_eq_cmpx         = (tmr == cmpx);
    wire        tmr_eq_cmpy         = (tmr == cmpy);

    always @(posedge clk, negedge rst_n)
        if (!rst_n)
            tmr_run <= 0;
        else if (tmr_en_pulse)
            tmr_run <= 1;
        else if (!tmr_periodic && tick && tmr_mode[0] &&
                 tmr_eq_one && !tmr_dir)
            tmr_run <= 0;

    // The timer
    reg [31:0]  tmr_reg_next;

    always @* begin
        tmr_reg_next = tmr_reg;
        if (tmr_start) begin
            case (tmr_mode)
                2'b01:   tmr_reg_next = tmr_reload;
                2'b10,
                2'b11:   tmr_reg_next = 32'd0;
                default: tmr_reg_next = tmr_reg;
            endcase
        end else begin
            case (tmr_mode)
                2'b11: begin
                    if (tmr_dir)
                        tmr_reg_next = tmr_reg + 1'b1;
                    else
                        tmr_reg_next = tmr_reg - 1'b1;
                end
                2'b01: begin
                    if (tmr_eq_zero)
                        tmr_reg_next = tmr_periodic ? tmr_reload : tmr_reg;
                    else
                        tmr_reg_next = tmr_reg - 1'b1;
                end
                2'b10: begin
                    if (tmr_eq_reload)
                        tmr_reg_next = tmr_periodic ? 32'd0 : tmr_reg;
                    else
                        tmr_reg_next = tmr_reg + 1'b1;
                end
                default: tmr_reg_next = tmr_reg;
            endcase
        end
    end

    always @(posedge clk, negedge rst_n)
        if (!rst_n)
            tmr_reg <= 0;
        else if (tmr_en_pulse) begin
            if (tmr_mode == 2'b01)
                tmr_reg <= tmr_reload;
            else
                tmr_reg <= 32'd0;
        end else if (tmr_en && tick && tmr_run)
            tmr_reg <= tmr_reg_next;

    // The counting direction flag
    always @(posedge clk, negedge rst_n)
        if (!rst_n)
            tmr_dir <= 1;
        else if (tmr_en_pulse) begin
            if (tmr_mode == 2'b01)
                tmr_dir <= 1'b0;
            else
                tmr_dir <= 1'b1;
        end else if (tick) begin
            if (tmr_mode == 2'b11) begin
                if (tmr_eq_one && !tmr_dir)
                    tmr_dir <= 1'b1;
                else if (tmr_eq_reload_m_1 && tmr_dir)
                    tmr_dir <= 1'b0;
            end else if (tmr_mode == 2'b10)
                tmr_dir <= 1'b1;
            else if (tmr_mode == 2'b01)
                tmr_dir <= 1'b0;
            else
                tmr_dir <= 1'b1;
        end

    // PWM Generator
    function pwm_action(input [1:0] action, input sig);
        case (action)
            2'b00: pwm_action = sig;
            2'b01: pwm_action = 0;
            2'b10: pwm_action = 1;
            2'b11: pwm_action = ~sig; 
        endcase
    endfunction 

    reg     pwm0_reg, pwm0_reg_next;
    reg     pwm1_reg, pwm1_reg_next;

    always @* begin
        casez({tmr_dir, tmr_eq_zero, tmr_eq_cmpx, tmr_eq_cmpy, tmr_eq_reload})
