    mapped    = 1'b1;
    read_only = 1'b0;

    if (addr[1:0] != 2'b00) begin
      mapped = 1'b0;
    end else begin
      case (addr)
        8'h00, 8'h04, 8'h08, 8'h0C,
        8'h10, 8'h14, 8'h18, 8'h1C,
        8'h20, 8'h24: begin
          mapped = 1'b1;
