              (((addr - 8'h40) >> 2) < NUM_PRIO_WORDS)) begin
            for (rj = 0; rj < 8; rj = rj + 1) begin
              ridx = (((addr - 8'h40) >> 2) * 8) + rj;
              if (ridx < NUM_SRC)
                rdata[(rj*4) +: PRIO_BITS] =
                    prio_flat[ridx*PRIO_BITS +: PRIO_BITS];
            end
          end
        end
      endcase
