      if (wr_en && !err) begin
        case (addr)
          8'h00: gen       <= wdata[0];
          8'h04: enable    <= wdata[NUM_SRC-1:0];
          8'h08: trigger   <= wdata[NUM_SRC-1:0];
          8'h14: threshold <= wdata[PRIO_BITS-1:0];
