      enable     <= {NUM_SRC{1'b0}};
      trigger    <= {NUM_SRC{1'b0}};
      in_service <= {NUM_SRC{1'b0}};
      threshold  <= {PRIO_BITS{1'b0}};
      prio_flat  <= {NUM_SRC*PRIO_BITS{1'b0}};
    end else begin
      if (wr_en && !err) begin
        case (addr)
          8'h00: gen       <= wdata[0];
          8'h04: enable    <= wdata[NUM_SRC-1:0];
          8'h08: trigger   <= wdata[NUM_SRC-1:0];
          8'h14: threshold <= wdata[PRIO_BITS-1:0];
          default: begin
            if ((addr >= 8'h40) &&
                (((addr - 8'h40) >> 2) < NUM_PRIO_WORDS)) begin
              for (wj = 0; wj < 8; wj = wj + 1) begin
                widx = (((addr - 8'h40) >> 2) * 8) + wj;
                if (widx < NUM_SRC)
                  prio_flat[widx*PRIO_BITS +: PRIO_BITS] <=
                      wdata[(wj*4) +: PRIO_BITS];
