          end
        endcase
      end

      for (si = 0; si < NUM_SRC; si = si + 1) begin
        if (wr_en && !err && (addr == 8'h18) &&
            (wdata == (si + 1)))
          in_service[si] <= 1'b0;
        else if (rd_en && !err && (addr == 8'h18) && irq &&
                 (irq_id == (si + 1)))
          in_service[si] <= 1'b1;
      end
    end
  end
