// APB interrupt controller: NUM_SRC sources, PRIO_BITS of priority each,
// claim/complete handshake. See spec.md for the full register map.

module intc_apb_if (
  input         PSEL,
  input         PENABLE,
  input         PWRITE,
  input  [7:0]  PADDR,
  input  [31:0] PWDATA,
  output [31:0] PRDATA,
  output        PREADY,
  output        PSLVERR,
  output        wr_en,
  output        rd_en,
  output [7:0]  addr,
  output [31:0] wdata,
  input  [31:0] rdata,
  input         err
);
  wire access = PSEL && PENABLE;

  assign wr_en   = access && PWRITE;
  assign rd_en   = access && !PWRITE;
  assign addr    = PADDR;
  assign wdata   = PWDATA;
  assign PREADY  = 1'b1;
  assign PSLVERR = access && err;
  assign PRDATA  = (rd_en && !err) ? rdata : 32'b0;
endmodule


module intc_sync #(
  parameter N = 8
) (
  input              clk,
  input              rst,
  input      [N-1:0] d,
  output reg [N-1:0] q
);
  reg [N-1:0] meta;

  always @(posedge clk) begin
    if (rst) begin
      meta <= 0;
      q    <= 0;
    end else begin
      meta <= d;
      q    <= meta;
    end
  end
endmodule


module intc_pending #(
  parameter N = 8
) (
  input              clk,
  input              rst,
  input      [N-1:0] src,
  input      [N-1:0] trigger,
  input      [N-1:0] clear_mask,
  input      [N-1:0] force_mask,
  output reg [N-1:0] pending
);
  reg [N-1:0] src_prev;

  wire [N-1:0] rise = src & ~src_prev;
  wire [N-1:0] set  = (trigger & rise) | (~trigger & src) | force_mask;

  always @(posedge clk) begin
    if (rst) begin
      src_prev <= 0;
      pending  <= 0;
    end else begin
      src_prev <= src;
      pending  <= (pending & ~clear_mask) | set;
    end
  end
endmodule


module intc_prio_select #(
  parameter N         = 8,
  parameter PRIO_BITS = 3
) (
  input      [N-1:0]           eligible,
  input      [N*PRIO_BITS-1:0] prio_flat,
  output reg                   best_valid,
  output reg [$clog2(N)-1:0]   best_idx,
  output reg [PRIO_BITS-1:0]   best_prio
);
  integer k;

  // Highest priority wins; strict > keeps the lowest index on a tie and
  // never selects a priority-0 source.
  always @(*) begin
    best_valid = 1'b0;
    best_idx   = 0;
    best_prio  = 0;
    for (k = 0; k < N; k = k + 1)
      if (eligible[k] && prio_flat[k*PRIO_BITS +: PRIO_BITS] > best_prio) begin
        best_valid = 1'b1;
        best_idx   = k;
        best_prio  = prio_flat[k*PRIO_BITS +: PRIO_BITS];
      end
  end
endmodule


module intc_regs #(
  parameter NUM_SRC   = 8,
  parameter PRIO_BITS = 3
) (
  input                              clk,
  input                              rst,
  input                              wr_en,
  input                              rd_en,
  input      [7:0]                   addr,
  input      [31:0]                  wdata,
  output reg [31:0]                  rdata,
  output                             err,
  input      [NUM_SRC-1:0]           pending,
  input                              irq,
  input      [$clog2(NUM_SRC+1)-1:0] irq_id,
  output reg                         gen,
  output reg [NUM_SRC-1:0]           enable,
  output reg [NUM_SRC-1:0]           trigger,
  output reg [NUM_SRC-1:0]           in_service,
  output reg [PRIO_BITS-1:0]         threshold,
  output reg [NUM_SRC*PRIO_BITS-1:0] prio_flat,
  output     [NUM_SRC-1:0]           clear_mask,
  output     [NUM_SRC-1:0]           force_mask
);
  localparam PRIO_WORDS = (NUM_SRC + 7) / 8;

  wire prio_addr =
      (addr >= 8'h40) &&
      (addr[1:0] == 2'b00) &&
      (((addr - 8'h40) >> 2) < PRIO_WORDS);

  wire mapped =
      (addr == 8'h00) ||
      (addr == 8'h04) ||
      (addr == 8'h08) ||
      (addr == 8'h0C) ||
      (addr == 8'h10) ||
      (addr == 8'h14) ||
      (addr == 8'h18) ||
      (addr == 8'h1C) ||
      (addr == 8'h20) ||
      (addr == 8'h24) ||
      prio_addr;

  wire readonly_write =
      wr_en &&
      ((addr == 8'h1C) || (addr == 8'h20) || (addr == 8'h24));

  assign err = (addr[1:0] != 2'b00) || !mapped || readonly_write;

  reg [NUM_SRC-1:0] clear_int;
  reg [NUM_SRC-1:0] force_int;
  integer clear_idx;

  always @(*) begin
    clear_int = {NUM_SRC{1'b0}};
    force_int = {NUM_SRC{1'b0}};

    if (wr_en && !err && addr == 8'h0C)
      clear_int = wdata[NUM_SRC-1:0];

    if (rd_en && !err && addr == 8'h18 &&
        irq && (irq_id != 0) && (irq_id <= NUM_SRC)) begin
      clear_idx = irq_id - 1'b1;
      clear_int[clear_idx] = 1'b1;
    end

    if (wr_en && !err && addr == 8'h10)
      force_int = wdata[NUM_SRC-1:0];
  end

  assign clear_mask = clear_int;
  assign force_mask = force_int;

  integer rd_j;
  integer rd_source;
  integer wr_j;
  integer wr_source;
  integer wr_word;

  always @(*) begin
    rdata = 32'b0;

    case (addr)
      8'h00: rdata[0] = gen;
      8'h04: rdata[NUM_SRC-1:0] = enable;
      8'h08: rdata[NUM_SRC-1:0] = trigger;
      8'h0C: rdata[NUM_SRC-1:0] = pending;
      8'h10: rdata = 32'b0;
      8'h14: rdata[PRIO_BITS-1:0] = threshold;
      8'h18: rdata = irq ? irq_id : 32'b0;
      8'h1C: rdata[NUM_SRC-1:0] = in_service;
      8'h20: begin
        rdata[0]    = irq;
        rdata[15:8] = irq_id;
      end
      8'h24: rdata = 32'h1C0D0000 + (PRIO_BITS << 8) + NUM_SRC;
      default: begin
        if (prio_addr) begin
          rd_j = 0;
          rd_source = 0;
          for (rd_j = 0; rd_j < 8; rd_j = rd_j + 1) begin
            rd_source = (((addr - 8'h40) >> 2) * 8) + rd_j;
            if (rd_source < NUM_SRC)
              rdata[rd_j*4 +: PRIO_BITS] =
                  prio_flat[rd_source*PRIO_BITS +: PRIO_BITS];
          end
        end
      end
    endcase
  end

  always @(posedge clk) begin
    if (rst) begin
      gen         <= 1'b0;
      enable      <= {NUM_SRC{1'b0}};
      trigger     <= {NUM_SRC{1'b0}};
      in_service  <= {NUM_SRC{1'b0}};
      threshold   <= {PRIO_BITS{1'b0}};
      prio_flat   <= {NUM_SRC*PRIO_BITS{1'b0}};
    end else begin
      if (wr_en && !err) begin
        case (addr)
          8'h00: gen       <= wdata[0];
          8'h04: enable    <= wdata[NUM_SRC-1:0];
          8'h08: trigger   <= wdata[NUM_SRC-1:0];
          8'h14: threshold <= wdata[PRIO_BITS-1:0];
          default: begin
            if (prio_addr) begin
              wr_word = (addr - 8'h40) >> 2;
              for (wr_j = 0; wr_j < 8; wr_j = wr_j + 1) begin
                wr_source = wr_word * 8 + wr_j;
                if (wr_source < NUM_SRC)
                  prio_flat[wr_source*PRIO_BITS +: PRIO_BITS]
                      <= wdata[wr_j*4 +: PRIO_BITS];
              end
            end
          end
        endcase
      end

      if (wr_en && !err && addr == 8'h18 &&
          (wdata >= 1) && (wdata <= NUM_SRC))
        in_service[wdata-1'b1] <= 1'b0;

      if (rd_en && !err && addr == 8'h18 &&
          irq && (irq_id != 0) && (irq_id <= NUM_SRC))
        in_service[irq_id-1'b1] <= 1'b1;
    end
  end
endmodule


module apb_intc #(
  parameter NUM_SRC   = 8,
  parameter PRIO_BITS = 3
) (
  input                              PCLK,
  input                              PRESETn,
  input                              PSEL,
  input                              PENABLE,
  input                              PWRITE,
  input  [7:0]                       PADDR,
  input  [31:0]                      PWDATA,
  output [31:0]                      PRDATA,
  output                             PREADY,
  output                             PSLVERR,
  input  [NUM_SRC-1:0]               irq_src,
  output                             irq,
  output [$clog2(NUM_SRC+1)-1:0]     irq_id
);
  wire rst = ~PRESETn;

  wire        wr_en;
  wire        rd_en;
  wire [7:0]  addr;
  wire [31:0] wdata;
  wire [31:0] rdata;
  wire        err;

  wire [NUM_SRC-1:0] src_sync;
  wire [NUM_SRC-1:0] pending;
  wire [NUM_SRC-1:0] enable;
  wire [NUM_SRC-1:0] trigger;
  wire [NUM_SRC-1:0] in_service;
  wire [NUM_SRC-1:0] clear_mask;
  wire [NUM_SRC-1:0] force_mask;
  wire [PRIO_BITS-1:0] threshold;
  wire [NUM_SRC*PRIO_BITS-1:0] prio_flat;
  wire gen;

  wire [NUM_SRC-1:0] eligible;
  wire best_valid;
  wire [$clog2(NUM_SRC)-1:0] best_idx;
  wire [PRIO_BITS-1:0] best_prio;

  intc_apb_if u_apb_if (
    .PSEL    (PSEL),
    .PENABLE (PENABLE),
    .PWRITE  (PWRITE),
    .PADDR   (PADDR),
    .PWDATA  (PWDATA),
    .PRDATA  (PRDATA),
    .PREADY  (PREADY),
    .PSLVERR (PSLVERR),
    .wr_en   (wr_en),
    .rd_en   (rd_en),
    .addr    (addr),
    .wdata   (wdata),
    .rdata   (rdata),
    .err     (err)
  );

  intc_sync #(
    .N(NUM_SRC)
  ) u_sync (
    .clk (PCLK),
    .rst (rst),
    .d   (irq_src),
    .q   (src_sync)
  );

  intc_pending #(
    .N(NUM_SRC)
  ) u_pending (
    .clk        (PCLK),
    .rst        (rst),
    .src        (src_sync),
    .trigger    (trigger),
    .clear_mask (clear_mask),
    .force_mask (force_mask),
    .pending    (pending)
  );

  intc_regs #(
    .NUM_SRC   (NUM_SRC),
    .PRIO_BITS (PRIO_BITS)
  ) u_regs (
    .clk        (PCLK),
    .rst        (rst),
    .wr_en      (wr_en),
    .rd_en      (rd_en),
    .addr       (addr),
    .wdata      (wdata),
    .rdata      (rdata),
    .err        (err),
    .pending    (pending),
    .irq        (irq),
    .irq_id     (irq_id),
    .gen        (gen),
    .enable     (enable),
    .trigger    (trigger),
    .in_service (in_service),
    .threshold  (threshold),
    .prio_flat  (prio_flat),
    .clear_mask (clear_mask),
    .force_mask (force_mask)
  );

  assign eligible = pending & enable & ~in_service;

  intc_prio_select #(
    .N         (NUM_SRC),
    .PRIO_BITS (PRIO_BITS)
  ) u_prio_select (
    .eligible  (eligible),
    .prio_flat (prio_flat),
    .best_valid(best_valid),
    .best_idx  (best_idx),
    .best_prio (best_prio)
  );

  assign irq    = gen && best_valid && (best_prio > threshold);
  assign irq_id = irq ? (best_idx + 1) : 0;
endmodule

