  wire [NUM_SRC-1:0]    pending;
  wire [NUM_SRC-1:0]    enable;
  wire [NUM_SRC-1:0]    trigger;
  wire [NUM_SRC-1:0]    in_service;
  wire [NUM_SRC-1:0]    clear_mask;
  wire [NUM_SRC-1:0]    force_mask;
  wire [PRIO_BITS-1:0]  threshold;
  wire [NUM_SRC*PRIO_BITS-1:0] prio_flat;

  wire [NUM_SRC-1:0] eligible;
  wire best_valid;
  wire [$clog2(NUM_SRC)-1:0] best_idx;
  wire [PRIO_BITS-1:0] best_prio;

  wire gen;

  intc_apb_if apb_if (
    .PSEL    (PSEL),
    .PENABLE (PENABLE),
    .PWRITE  (PWRITE),
    .PADDR   (PADDR),
    .PWDATA  (PWDATA),
    .PRDATA  (PRDATA),
    .PREADY  (PREADY),
    .PSLVERR (PSLVERR),
    .wr_en   (wr_en),
    .rd_en   (rd_en),
    .addr    (addr),
    .wdata   (wdata),
    .rdata   (rdata),
    .err     (err)
  );

  intc_sync #(
    .N(NUM_SRC)
  ) sync_inputs (
    .clk (PCLK),
    .rst (rst),
    .d   (irq_src),
    .q   (src_sync)
  );

  intc_pending #(
    .N(NUM_SRC)
  ) pending_logic (
    .clk        (PCLK),
    .rst        (rst),
    .src        (src_sync),
    .trigger    (trigger),
    .clear_mask (clear_mask),
    .force_mask (force_mask),
    .pending    (pending)
  );

  assign eligible = pending & enable & ~in_service;

  intc_prio_select #(
    .N         (NUM_SRC),
    .PRIO_BITS (PRIO_BITS)
  ) priority_select (
    .eligible  (eligible),
    .prio_flat (prio_flat),
    .best_valid(best_valid),
    .best_idx  (best_idx),
    .best_prio (best_prio)
  );

  assign irq    = gen && best_valid && (best_prio > threshold);
  assign irq_id = irq ? (best_idx + 1'b1) : {($clog2(NUM_SRC+1)){1'b0}};

  intc_regs #(
    .NUM_SRC   (NUM_SRC),
    .PRIO_BITS (PRIO_BITS)
  ) registers (
    .clk        (PCLK),
    .rst        (rst),
    .wr_en      (wr_en),
    .rd_en      (rd_en),
    .addr       (addr),
    .wdata      (wdata),
    .rdata      (rdata),
    .err        (err),
    .pending    (pending),
    .irq        (irq),
    .irq_id     (irq_id),
    .gen        (gen),
    .enable     (enable),
    .trigger    (trigger),
    .in_service (in_service),
    .threshold  (threshold),
    .prio_flat  (prio_flat),
    .clear_mask (clear_mask),
    .force_mask (force_mask)
  );
endmodule

