module intc_regs #(
  parameter NUM_SRC   = 8,
  parameter PRIO_BITS = 3
) (
  input                              clk,
  input                              rst,
  input                              wr_en,
  input                              rd_en,
  input      [7:0]                   addr,
  input      [31:0]                  wdata,
  output reg [31:0]                  rdata,
  output                             err,
  input      [NUM_SRC-1:0]           pending,
  input                              irq,
  input      [$clog2(NUM_SRC+1)-1:0] irq_id,
  output reg                         gen,
  output reg [NUM_SRC-1:0]           enable,
