        if (!rst_n)
            pwm0_reg <= 0;
        else if (pwm0_en && tick) begin
            if (pwm_fault)
                pwm0_reg <= 0;
            else
                pwm0_reg <= pwm0_reg_next;
        end

    always @(posedge clk, negedge rst_n)
        if (!rst_n)
            pwm1_reg <= 0;
        else if (pwm1_en && tick) begin
            if (pwm_fault)
                pwm1_reg <= 0;
            else
                pwm1_reg <= pwm1_reg_next;
        end

    // Dead time insertion
    reg pwm0_delayed;
    reg [7:0] dly_cntr;
    always @(posedge clk, negedge rst_n)
        if (!rst_n)
            dly_cntr <= 0;
        else if (tick) begin
            if (dly_cntr == 0)
                dly_cntr <= pwm_dt;
            else
                dly_cntr <= dly_cntr - 1;
