)
(
    input   wire            clk,
    input   wire            rst_n,

    input   wire            tmr_en,
    input   wire            tmr_start,
    input   wire            pwm0_en,
    input   wire            pwm1_en,
    input   wire [31:0]     tmr_reload,
    input   wire [31:0]     cmpx,
    input   wire [31:0]     cmpy,
    input   wire [PRW-1:0]  prescaler,
    input   wire [ 2:0]     tmr_cfg,     // [2]: Periodic/OneShot; [1:0]: 10: Up, 01: Down, 11: Up/Down
    input   wire [11:0]     pwm0_cfg,
    input   wire [11:0]     pwm1_cfg,
    input   wire            pwm0_inv,
    input   wire            pwm1_inv,
    input   wire [ 7:0]     pwm_dt,
    input   wire [15:0]     pwm_fault_clr,
    input   wire            pwm_dt_en,

    output  wire [31:0]     tmr,
    output  wire            matchx_flag,
    output  wire            matchy_flag,
    output  wire            timeout_flag,

    input   wire            pwm_fault,
    output  wire            pwm0,
    output  wire            pwm1
);
    reg [PRW-1:0] prescale_count;
    reg [31:0] tmr_reg;
    reg running;
    reg dir_down;

    wire start_pulse;
    wire tick = (prescale_count == {PRW{1'b0}});

    ef_util_ped start_detector (
        .clk(clk),
        .in(tmr_en),
        .out(start_pulse)
    );

    assign tmr = tmr_reg;
    assign matchx_flag = (tmr_reg == cmpx);
    assign matchy_flag = (tmr_reg == cmpy);
    assign timeout_flag = dir_down ? (tmr_reg == 32'd0) :
                                      (tmr_reg == tmr_reload);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            prescale_count <= {{(PRW-1){1'b0}}, 1'b1};
        else if (!tmr_en)
            prescale_count <= prescaler;
        else if (tick)
            prescale_count <= prescaler;
        else
            prescale_count <= prescale_count - {{(PRW-1){1'b0}}, 1'b1};
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            tmr_reg <= 32'd0;
            running <= 1'b0;
            dir_down <= 1'b0;
        end else begin
            if (start_pulse) begin
                tmr_reg <= (tmr_cfg[1:0] == 2'b01) ? tmr_reload : 32'd0;
                dir_down <= (tmr_cfg[1:0] == 2'b01);
                running <= 1'b1;
            end else begin
                if (tick) begin
                    case (tmr_cfg[1:0])
                        2'b01: dir_down <= 1'b1;
                        2'b10: dir_down <= 1'b0;
                        2'b00: dir_down <= 1'b0;
                        2'b11: begin
                            if (!dir_down && (tmr_reg == (tmr_reload - 32'd1)))
                                dir_down <= 1'b1;
                            else if (dir_down && (tmr_reg == 32'd1))
                                dir_down <= 1'b0;
                        end
                    endcase
