                if (tmr_en && tick && running) begin
                    if (tmr_start && (tmr_cfg[1:0] == 2'b01)) begin
                        tmr_reg <= tmr_reload;
                    end else if (tmr_start &&
                                 ((tmr_cfg[1:0] == 2'b10) ||
                                  (tmr_cfg[1:0] == 2'b11))) begin
                        tmr_reg <= 32'd0;
                    end else begin
                        case (tmr_cfg[1:0])
                            2'b11: begin
                                if (dir_down)
                                    tmr_reg <= tmr_reg - 32'd1;
                                else
                                    tmr_reg <= tmr_reg + 32'd1;
                            end
                            2'b01: begin
                                if (tmr_reg == 32'd0) begin
                                    if (tmr_cfg[2])
                                        tmr_reg <= tmr_reload;
                                end else begin
                                    tmr_reg <= tmr_reg - 32'd1;
                                end
                            end
                            2'b10: begin
                                if (tmr_reg == tmr_reload) begin
                                    if (tmr_cfg[2])
                                        tmr_reg <= 32'd0;
                                end else begin
                                    tmr_reg <= tmr_reg + 32'd1;
                                end
                            end
                            default: tmr_reg <= tmr_reg;
                        endcase
                    end

                    if (!tmr_cfg[2] && tmr_cfg[0] &&
                        (tmr_reg == 32'd1) && dir_down)
                        running <= 1'b0;
                end
            end
        end
    end

    wire common_unequal = (tmr_reg != cmpx) &&
                          (tmr_reg != cmpy) &&
                          (tmr_reg != tmr_reload);
    wire event_zero = (tmr_reg == 32'd0) && common_unequal;
    wire event_cmpx_up = !dir_down && (tmr_reg == cmpx) &&
                         (tmr_reg != 32'd0) && (tmr_reg != cmpy) &&
                         (tmr_reg != tmr_reload);
    wire event_cmpy_up = !dir_down && (tmr_reg == cmpy) &&
                         (tmr_reg != 32'd0) && (tmr_reg != cmpx) &&
                         (tmr_reg != tmr_reload);
    wire event_reload = (tmr_reg == tmr_reload) &&
                        (tmr_reg != 32'd0) && (tmr_reg != cmpx) &&
                        (tmr_reg != cmpy);
    wire event_cmpy_down = dir_down && (tmr_reg == cmpy) &&
                           (tmr_reg != 32'd0) && (tmr_reg != cmpx) &&
                           (tmr_reg != tmr_reload);
    wire event_cmpx_down = dir_down && (tmr_reg == cmpx) &&
                           (tmr_reg != 32'd0) && (tmr_reg != cmpy) &&
                           (tmr_reg != tmr_reload);

    reg pwm0_state;
    reg pwm1_state;
    reg pwm_fault_armed;
    reg pwm_fault_latched;
    reg [7:0] dead_time_count;
    reg pwm0_delayed;
    reg pwm0_out_reg;
    reg pwm1_out_reg;

