                    pwm0_state <= 1'b0;
                end else if (event_zero) begin
                    case (pwm0_cfg[1:0])
                        2'b01: pwm0_state <= 1'b0;
                        2'b10: pwm0_state <= 1'b1;
                        2'b11: pwm0_state <= ~pwm0_state;
                        default: pwm0_state <= pwm0_state;
                    endcase
                end else if (event_cmpx_up) begin
                    case (pwm0_cfg[3:2])
                        2'b01: pwm0_state <= 1'b0;
                        2'b10: pwm0_state <= 1'b1;
                        2'b11: pwm0_state <= ~pwm0_state;
                        default: pwm0_state <= pwm0_state;
                    endcase
                end else if (event_cmpy_up) begin
                    case (pwm0_cfg[5:4])
                        2'b01: pwm0_state <= 1'b0;
                        2'b10: pwm0_state <= 1'b1;
                        2'b11: pwm0_state <= ~pwm0_state;
                        default: pwm0_state <= pwm0_state;
                    endcase
                end else if (event_reload) begin
                    case (pwm0_cfg[7:6])
                        2'b01: pwm0_state <= 1'b0;
                        2'b10: pwm0_state <= 1'b1;
                        2'b11: pwm0_state <= ~pwm0_state;
                        default: pwm0_state <= pwm0_state;
                    endcase
                end else if (event_cmpy_down) begin
                    case (pwm0_cfg[9:8])
                        2'b01: pwm0_state <= 1'b0;
                        2'b10: pwm0_state <= 1'b1;
                        2'b11: pwm0_state <= ~pwm0_state;
                        default: pwm0_state <= pwm0_state;
                    endcase
                end else if (event_cmpx_down) begin
                    case (pwm0_cfg[11:10])
                        2'b01: pwm0_state <= 1'b0;
                        2'b10: pwm0_state <= 1'b1;
                        2'b11: pwm0_state <= ~pwm0_state;
                        default: pwm0_state <= pwm0_state;
                    endcase
                end
            end

