                if (pwm_fault) begin
                    pwm1_state <= 1'b0;
                end else if (event_zero) begin
                    case (pwm1_cfg[1:0])
                        2'b01: pwm1_state <= 1'b0;
                        2'b10: pwm1_state <= 1'b1;
                        2'b11: pwm1_state <= ~pwm1_state;
                        default: pwm1_state <= pwm1_state;
                    endcase
                end else if (event_cmpx_up) begin
                    case (pwm1_cfg[3:2])
                        2'b01: pwm1_state <= 1'b0;
                        2'b10: pwm1_state <= 1'b1;
                        2'b11: pwm1_state <= ~pwm1_state;
                        default: pwm1_state <= pwm1_state;
                    endcase
                end else if (event_cmpy_up) begin
                    case (pwm1_cfg[5:4])
                        2'b01: pwm1_state <= 1'b0;
                        2'b10: pwm1_state <= 1'b1;
                        2'b11: pwm1_state <= ~pwm1_state;
                        default: pwm1_state <= pwm1_state;
                    endcase
                end else if (event_reload) begin
