  always @(posedge clk) begin
    if (rst) begin
      grant <= 0;
      last  <= N - 1;
    end else if (found) begin
      grant <= 1 << pick;
      last  <= pick;
    end else
      grant <= 0;
  end

  assign last_idx = last;
endmodule

