  always @(posedge clk) begin
    if (rst) begin
      state       <= S_GREEN;
      timer       <= 0;
      ped_pending <= 1'b0;
    end else begin
      if (state == S_RED)
        ped_pending <= 1'b0;
      else if (ped)
        ped_pending <= 1'b1;

