      read_ptr  <= {AW{1'b0}};
      write_ptr <= {AW{1'b0}};
      count     <= {(AW+1){1'b0}};
    end else if (flush) begin
      read_ptr  <= {AW{1'b0}};
      write_ptr <= {AW{1'b0}};
      count     <= {(AW+1){1'b0}};
    end else begin
      if (accepted_write) begin
        memory[write_ptr] <= wdata;
        write_ptr <= write_ptr + 1'b1;
      end

      if (advance_read)
        read_ptr <= read_ptr + 1'b1;

      if (accepted_write && !rd)
        count <= count + 1'b1;
      else if (!accepted_write && rd && !empty)
        count <= count - 1'b1;
    end
  end
