/*
    UART Receiver
*/
module UART_RX #(parameter NUM_SAMPLES = 16, MDW = 8)(
    input   wire            clk,
    input   wire            resetn,
    input   wire            b_tick,             // Baud generator tick
    input   wire [3:0]      data_size,          // 5 - 9
    input   wire            stop_bits_count,    // 0: 1, 1: 2
    input   wire [2:0]      parity_type,        // 000: None, 001: odd, 010: even, 
                                                // 100: Sticky 0, 101: Sticky 1
    input   wire            rx,                 // RS-232 data port
    input   wire [MDW-1:0]  match_data,
    output  reg             rx_done,            // Transfer completed
    output  reg             parity_error,       // Parity Error
    output  reg             frame_error,        // Framing Error
    output  reg             break_flag,         // Break flag
    output  reg             match_flag,
    output  wire [MDW-1:0]  dout                // Received data
);
  localparam IDLE = 3'd0, START = 3'd1, DATA = 3'd2,
             PARITY = 3'd3, STOP = 3'd4;

  reg [2:0] state;
  reg [31:0] sample_counter;
  reg [31:0] data_index;
  reg [31:0] data_count;
  reg [MDW-1:0] data_reg;
  reg parity_bad;
  reg stop_bad;
  reg stop_index;
  reg [3:0] low_samples;
  reg expected_parity;
  integer i;

  assign dout = data_reg;

  always @* begin
    expected_parity = 1'b0;
    case (parity_type)
      3'b001: expected_parity = ~(^data_reg);
      3'b010: expected_parity =  (^data_reg);
      3'b100: expected_parity = 1'b0;
      3'b101: expected_parity = 1'b1;
      default: expected_parity = 1'b0;
    endcase
  end

  always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
      state            <= IDLE;
      sample_counter   <= 0;
      data_index       <= 0;
      data_count       <= 8;
      data_reg         <= {MDW{1'b0}};
      parity_bad       <= 1'b0;
      stop_bad         <= 1'b0;
      stop_index       <= 1'b0;
      low_samples      <= 0;
      rx_done          <= 1'b0;
      parity_error     <= 1'b0;
      frame_error      <= 1'b0;
      break_flag       <= 1'b0;
      match_flag       <= 1'b0;
    end else begin
      rx_done      <= 1'b0;
      parity_error <= 1'b0;
      frame_error  <= 1'b0;
      break_flag   <= 1'b0;
      match_flag   <= 1'b0;

      if (b_tick) begin
        case (state)
          IDLE: begin
            if (!rx) begin
              state          <= START;
              sample_counter <= 0;
              data_index     <= 0;
              data_count     <= (data_size >= 5 && data_size <= 9) ? data_size : 8;
              data_reg       <= {MDW{1'b0}};
              parity_bad     <= 1'b0;
              stop_bad       <= 1'b0;
              stop_index     <= 1'b0;
            end
          end

          START: begin
            if (sample_counter >= ((NUM_SAMPLES/2) > 0 ? (NUM_SAMPLES/2)-1 : 0)) begin
              sample_counter <= 0;
              state <= DATA;
            end else begin
              sample_counter <= sample_counter + 1'b1;
            end
          end

          DATA: begin
            if (sample_counter == NUM_SAMPLES-1) begin
              sample_counter <= 0;
              data_reg[data_index] <= rx;
              if (data_index == data_count-1) begin
                data_index <= 0;
                if (parity_type != 3'b000)
                  state <= PARITY;
                else begin
                  state <= STOP;
                  stop_index <= 1'b0;
                end
              end else begin
                data_index <= data_index + 1'b1;
              end

              if (!rx) begin
                if (low_samples == 4'd11)
                  break_flag <= 1'b1;
                if (low_samples < 4'd12)
                  low_samples <= low_samples + 1'b1;
              end else begin
                low_samples <= 0;
              end
            end else begin
              sample_counter <= sample_counter + 1'b1;
            end
          end

          PARITY: begin
            if (sample_counter == NUM_SAMPLES-1) begin
              sample_counter <= 0;
              parity_bad <= (parity_type == 3'b001 ||
                             parity_type == 3'b010 ||
                             parity_type == 3'b100 ||
                             parity_type == 3'b101) &&
                            (rx != expected_parity);
              state <= STOP;

              if (!rx) begin
                if (low_samples == 4'd11)
                  break_flag <= 1'b1;
                if (low_samples < 4'd12)
                  low_samples <= low_samples + 1'b1;
              end else begin
                low_samples <= 0;
              end
            end else begin
              sample_counter <= sample_counter + 1'b1;
            end
          end

          STOP: begin
            if (sample_counter == NUM_SAMPLES-1) begin
              sample_counter <= 0;
              if (!rx) begin
                if (low_samples == 4'd11)
                  break_flag <= 1'b1;
                if (low_samples < 4'd12)
                  low_samples <= low_samples + 1'b1;
              end else begin
                low_samples <= 0;
              end

              if (stop_bits_count && !stop_index) begin
                stop_bad   <= !rx;
                stop_index <= 1'b1;
              end else begin
                rx_done      <= 1'b1;
                parity_error <= parity_bad;
                frame_error  <= stop_bits_count && stop_bad;
                match_flag   <= (data_reg == match_data);
                state        <= IDLE;
              end
            end else begin
              sample_counter <= sample_counter + 1'b1;
            end
          end

          default: begin
            state <= IDLE;
          end
        endcase
      end
    end
  end
endmodule

/*
    UART Transmitter
*/
module UART_TX #(parameter NUM_SAMPLES = 16, MDW = 8)(
    input   wire                clk,
    input   wire                resetn,
    input   wire                tx_start,        
    input   wire                b_tick,             //baud rate tick
    input   wire [3:0]          data_size,          // 5 - 9
    input   wire                stop_bits_count,    // 0: 1, 1: 2
    input   wire [2:0]          parity_type,        // 000: None, 001: odd, 010: even, 
                                                    // 100: Sticky 0, 101: Sticky 1
    input   wire [MDW-1:0]      d_in,               // input data to transmit
    output  reg                 tx_done,            // Transfer finished
    output  wire                tx                  // output data to RS-232
);
  localparam IDLE = 3'd0, START = 3'd1, DATA = 3'd2,
             PARITY = 3'd3, STOP = 3'd4;

  reg [2:0] state;
  reg [31:0] tick_counter;
  reg [31:0] data_index;
  reg [31:0] data_count;
  reg [31:0] stop_index;
  reg [MDW-1:0] data_reg;
  reg [MDW-1:0] tx_data;
  reg serial_reg;
  reg parity_bit;

  assign tx = serial_reg;

  always @* begin
    case (parity_type)
      3'b001: parity_bit = ~(^d_in[data_count-1:0]);
      3'b010: parity_bit =  (^d_in[data_count-1:0]);
      3'b100: parity_bit = 1'b0;
      3'b101: parity_bit = 1'b1;
      default: parity_bit = 1'b0;
    endcase
  end

  always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
      state       <= IDLE;
      tick_counter <= 0;
      data_index  <= 0;
      data_count  <= 8;
      stop_index  <= 0;
      data_reg    <= {MDW{1'b0}};
      serial_reg  <= 1'b1;
      tx_done     <= 1'b0;
    end else begin
      tx_done <= 1'b0;

      case (state)
        IDLE: begin
          serial_reg <= 1'b1;
          if (tx_start) begin
            state        <= START;
            tick_counter <= 0;
            data_index   <= 0;
            data_count   <= (data_size >= 5 && data_size <= 9) ? data_size : 8;
            data_reg     <= d_in;
            stop_index   <= 0;
          end
        end

        START: begin
          serial_reg <= 1'b0;
          if (b_tick) begin
            if (tick_counter == NUM_SAMPLES) begin
              tick_counter <= 0;
              state <= DATA;
            end else begin
              tick_counter <= tick_counter + 1'b1;
            end
          end
        end

        DATA: begin
          serial_reg <= data_reg[data_index];
          if (b_tick) begin
            if (tick_counter == NUM_SAMPLES-1) begin
              tick_counter <= 0;
              if (data_index == data_count-1) begin
                data_index <= 0;
                if (parity_type != 3'b000)
                  state <= PARITY;
                else begin
                  state <= STOP;
                  stop_index <= 0;
                end
              end else begin
                data_index <= data_index + 1'b1;
              end
            end else begin
              tick_counter <= tick_counter + 1'b1;
            end
          end
        end

        PARITY: begin
          serial_reg <= parity_bit;
          if (b_tick) begin
            if (tick_counter == NUM_SAMPLES-1) begin
              tick_counter <= 0;
              state <= STOP;
              stop_index <= 0;
            end else begin
              tick_counter <= tick_counter + 1'b1;
            end
          end
        end

        STOP: begin
          serial_reg <= 1'b1;
          if (b_tick) begin
            if (tick_counter == NUM_SAMPLES-1) begin
              tick_counter <= 0;
              if (stop_bits_count && !stop_index) begin
                stop_index <= 1;
              end else begin
                state   <= IDLE;
                tx_done <= 1'b1;
              end
            end else begin
              tick_counter <= tick_counter + 1'b1;
            end
          end
        end

        default: begin
          state      <= IDLE;
          serial_reg <= 1'b1;
        end
      endcase
    end
  end
endmodule

