  always @(posedge PCLK or negedge PRESETn) begin
    if (!PRESETn) begin
      prescaler_reg    <= 16'd0;
      ctrl_reg         <= 5'd0;
      cfg_reg          <= 14'h3f08;
      match_reg        <= {MDW{1'b0}};
      rx_threshold_reg <= 4'd0;
      tx_threshold_reg <= 4'd0;
      rx_flush_reg     <= 1'b0;
      tx_flush_reg     <= 1'b0;
      im_reg           <= 10'd0;
      ic_reg           <= 10'd0;
      gclk_reg         <= 1'b0;
    end else begin
      rx_flush_reg <= 1'b0;
      tx_flush_reg <= 1'b0;
      ic_reg       <= 10'd0;

      if (write_transfer) begin
        case (PADDR[15:0])
          ADDR_PR:           prescaler_reg    <= PWDATA[15:0];
          ADDR_CTRL:         ctrl_reg         <= PWDATA[4:0];
          ADDR_CFG:          cfg_reg          <= PWDATA[13:0];
          ADDR_MATCH:        match_reg        <= PWDATA[MDW-1:0];
          ADDR_RX_THRESHOLD: rx_threshold_reg <= PWDATA[3:0];
          ADDR_TX_THRESHOLD: tx_threshold_reg <= PWDATA[3:0];
          ADDR_RX_FLUSH:     rx_flush_reg     <= PWDATA[0];
          ADDR_TX_FLUSH:     tx_flush_reg     <= PWDATA[0];
          ADDR_IM:           im_reg           <= PWDATA[9:0];
          ADDR_IC:           ic_reg           <= PWDATA[9:0];
          ADDR_GCLK:         gclk_reg         <= PWDATA[0];
