  always @(posedge PCLK or negedge PRESETn) begin
    if (!PRESETn) begin
      ris_reg <= 10'd0;
    end else begin
      if (|(ris_reg & ic_reg))
        ris_reg <= ris_reg & ~ic_reg;
      else
        ris_reg <= ris_reg | interrupt_conditions;
    end
  end

  reg [31:0] read_data;
  always @* begin
    case (PADDR[15:0])
      ADDR_RXDATA:       read_data = {{(32-MDW){1'b0}}, rx_fifo_data};
      ADDR_PR:           read_data = {16'd0, prescaler_reg};
      ADDR_CTRL:         read_data = {27'd0, ctrl_reg};
      ADDR_CFG:          read_data = {18'd0, cfg_reg};
      ADDR_MATCH:        read_data = {{(32-MDW){1'b0}}, match_reg};
      ADDR_RX_LEVEL:     read_data = {{(32-FAW){1'b0}}, rx_level};
      ADDR_RX_THRESHOLD: read_data = {28'd0, rx_threshold_reg};
      ADDR_RX_FLUSH:     read_data = {31'd0, rx_flush_reg};
      ADDR_TX_LEVEL:     read_data = {{(32-FAW){1'b0}}, tx_level};
      ADDR_TX_THRESHOLD: read_data = {28'd0, tx_threshold_reg};
      ADDR_TX_FLUSH:     read_data = {31'd0, tx_flush_reg};
      ADDR_IM:           read_data = {22'd0, im_reg};
      ADDR_MIS:          read_data = {22'd0, (ris_reg & im_reg)};
      ADDR_RIS:          read_data = {22'd0, ris_reg};
      ADDR_GCLK:         read_data = {31'd0, gclk_reg};
      default:           read_data = 32'hdeadbeef;
    endcase
  end

  assign PRDATA = read_data;
endmodule

