// From efabless/EF_IP_UTIL hdl/ef_util_lib.v (commit a2b3fb6): the modules EF_UART needs.
module ef_util_sync #(parameter NUM_STAGES = 2) (
    input wire clk,
    input wire in,
    output wire out
);
  reg [NUM_STAGES-1:0] sync_reg;

  always @(posedge clk)
    sync_reg <= {sync_reg[NUM_STAGES-2:0], in};

  assign out = sync_reg[NUM_STAGES-1];
endmodule

module ef_util_ticker #(parameter W=8) (
    input   wire            clk, 
    input   wire            rst_n,
    input   wire            en,
    input   wire [W-1:0]    clk_div,
    output  wire            tick
);
  reg [W-1:0] counter;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
      counter <= {W{1'b0}};
    else if (en) begin
      if (counter == clk_div)
        counter <= {W{1'b0}};
      else
        counter <= counter + {{W-1{1'b0}}, 1'b1};
    end
  end

  assign tick = (counter == clk_div);
endmodule

module ef_util_glitch_filter #(parameter N = 8, CLKDIV = 8'd1) (
    input   wire    clk,
    input   wire    rst_n,
    input   wire    in,
    input   wire    en,
    output  reg     out
);
  reg [N-1:0] stages;
  reg [7:0] counter;
  reg tick;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      counter <= 8'd0;
      tick    <= 1'b0;
    end else begin
      if (en) begin
        if (counter == 0)
          counter <= CLKDIV;
        else
          counter <= counter - 1'b1;
        tick <= (counter == 0);
      end else begin
        tick <= 1'b0;
      end
    end
  end

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      stages <= {N{1'b0}};
      out    <= 1'b0;
    end else begin
      if (tick)
        stages <= {stages[N-2:0], in};

      if (&stages)
        out <= 1'b1;
      else if (~|stages)
        out <= 1'b0;
    end
  end
endmodule

module ef_util_fifo #(parameter DW=8, AW=4)(
    input   wire            clk,
    input   wire            rst_n,
    input   wire            rd,
    input   wire            wr,
    input   wire            flush,
    input   wire [DW-1:0]   wdata,
    output  wire            empty,
    output  wire            full,
    output  wire [DW-1:0]   rdata,
    output  wire [AW-1:0]   level    
);
  localparam DEPTH = (1 << AW);

  reg [DW-1:0] memory [0:DEPTH-1];
  reg [AW-1:0] read_ptr;
  reg [AW-1:0] write_ptr;
  reg [AW:0] count;

  wire accepted_write = wr && !full;
  wire advance_read = rd && (!empty || accepted_write);

  assign empty = (count == 0);
  assign full  = (count == DEPTH);
  assign level = count[AW-1:0];
  assign rdata = memory[read_ptr];

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      read_ptr  <= {AW{1'b0}};
      write_ptr <= {AW{1'b0}};
      count     <= {(AW+1){1'b0}};
    end else if (flush) begin
      read_ptr  <= {AW{1'b0}};
      write_ptr <= {AW{1'b0}};
      count     <= {(AW+1){1'b0}};
    end else begin
      if (accepted_write) begin
        memory[write_ptr] <= wdata;
        write_ptr <= write_ptr + 1'b1;
      end

      if (advance_read)
        read_ptr <= read_ptr + 1'b1;

      if (accepted_write && !rd)
        count <= count + 1'b1;
      else if (!accepted_write && rd && !empty)
        count <= count - 1'b1;
    end
  end
endmodule

