/*
    A Universal Asynchronous Receiver/Transmitter (UART) 
    - Programmable frame format
        - Data: 5-9 bits
        - Parity: None, Odd, Even, or Sticky at 0/1
    - TX and RX FIFOs with programmable thresholds
    - 16-bit prescaler (PR) for programable baud rate generation
    - Baudrate = CLK/((PR+1)*NUM_SAMPLES)
    - RX synchronizer
    - RX Glich Filter
    - Interrupt Sources:
        + TX fifo not full
        + RX fifo not empty
        + RX fifo level exceeded the threshold
        + TX fifo level is below the threshold
        + Framing Error
        + Parity Error
        + Break is observed
        + Timeout: Nothing received for the time of 4 frames!
*/

`timescale			1ns/1ps
`default_nettype		none


module EF_UART #(parameter  MDW = 9,        // Max data size/width
                                FAW = 4,        // FIFO Address width; Depth=2^AW
                                SC = 8,         // Number of samples per bit/baud
                                GFLEN = 8       // Length (number of stages) of the glitch filter
) (
    input   wire            clk,
    input   wire            rst_n,

    input   wire [15:0]     prescaler,
    input   wire            en,
    input   wire            tx_en,
    input   wire            rx_en,
    input   wire            rd,
    input   wire            wr,
    input   wire [MDW-1:0]  wdata,
    input   wire [3:0]      data_size,          // 5 - 9
    input   wire            stop_bits_count,    // 0: 1, 1: 2
    input   wire [2:0]      parity_type,        // 000: None, 001: odd, 010: even, 100: Sticky 0, 101: Sticky 1
    input   wire [3:0]      txfifotr,
    input   wire [3:0]      rxfifotr,
    input   wire [MDW-1:0]  match_data,
    input   wire [5:0]      timeout_bits,
    input   wire            loopback_en,
    input   wire            glitch_filter_en,
    input   wire            tx_fifo_flush,
    input   wire            rx_fifo_flush,

    output  wire            tx_empty,
    output  wire            tx_full,
    output  wire [FAW-1:0]  tx_level,
    output  wire            tx_level_below,
    output  wire [MDW-1:0]  rdata,
    output  wire            rx_empty,
    output  wire            rx_full,
    output  wire [FAW-1:0]  rx_level,
    output  wire            rx_level_above,

    output  wire            break_flag,
    output  wire            match_flag,
    output  wire            frame_error_flag,
    output  wire            parity_error_flag,
    output  wire            overrun_flag,
    output  wire            timeout_flag,

    input   wire            rx,
    output  wire            tx
);
  wire baudtick;
  wire rx_sync;
  wire rx_filtered;
  wire rx_input;
  wire tx_done;
  wire rx_done;
  wire rx_parity_error;
  wire rx_frame_error;
  wire rx_break;
  wire rx_match;
  wire [MDW-1:0] rx_data;
  wire tx_fifo_read;
  wire rx_fifo_write;
  wire [MDW-1:0] tx_head;
  wire [5:0] bit_counter;
  reg [31:0] timeout_tick_counter;
  reg [5:0] timeout_bit_counter;

  BAUDGEN baud_generator (
    .clk(clk),
    .rst_n(rst_n),
    .prescale(prescaler),
    .en(en),
    .baudtick(baudtick)
  );

  ef_util_sync #(.NUM_STAGES(2)) rx_synchronizer (
    .clk(clk),
    .in(rx),
    .out(rx_sync)
  );

  ef_util_glitch_filter #(.N(GFLEN), .CLKDIV(8'd1)) input_filter (
    .clk(clk),
    .rst_n(rst_n),
    .in(rx_sync),
    .en(glitch_filter_en),
    .out(rx_filtered)
  );

  assign rx_input = loopback_en ? tx :
                    glitch_filter_en ? rx_filtered : rx_sync;

  ef_util_fifo #(.DW(MDW), .AW(FAW)) tx_fifo (
    .clk(clk),
    .rst_n(rst_n),
    .rd(tx_fifo_read),
    .wr(wr),
    .flush(tx_fifo_flush),
    .wdata(wdata),
    .empty(tx_empty),
    .full(tx_full),
    .rdata(tx_head),
    .level(tx_level)
  );

  assign tx_fifo_read = tx_done;

  ef_util_fifo #(.DW(MDW), .AW(FAW)) rx_fifo (
    .clk(clk),
    .rst_n(rst_n),
    .rd(rd),
    .wr(rx_fifo_write),
    .flush(rx_fifo_flush),
    .wdata(rx_data),
    .empty(rx_empty),
    .full(rx_full),
    .rdata(rdata),
    .level(rx_level)
  );

  assign rx_fifo_write = rx_done;
  assign tx_level_below = (tx_level < txfifotr) && !tx_full;
  assign rx_level_above = (rx_level > rxfifotr) || rx_full;

  UART_TX #(.NUM_SAMPLES(SC), .MDW(MDW)) transmitter (
    .clk(clk),
    .resetn(rst_n),
    .tx_start(!tx_empty),
    .b_tick(baudtick && tx_en),
    .data_size(data_size),
    .stop_bits_count(stop_bits_count),
    .parity_type(parity_type),
    .d_in(tx_head),
    .tx_done(tx_done),
    .tx(tx)
  );

  UART_RX #(.NUM_SAMPLES(SC), .MDW(MDW)) receiver (
    .clk(clk),
    .resetn(rst_n),
    .b_tick(baudtick && rx_en),
    .data_size(data_size),
    .stop_bits_count(stop_bits_count),
    .parity_type(parity_type),
    .rx(rx_input),
    .match_data(match_data),
    .rx_done(rx_done),
    .parity_error(rx_parity_error),
    .frame_error(rx_frame_error),
    .break_flag(rx_break),
    .match_flag(rx_match),
    .dout(rx_data)
  );

  assign break_flag       = rx_break;
  assign match_flag       = rx_match;
  assign frame_error_flag = rx_frame_error;
  assign parity_error_flag = rx_parity_error;
  assign overrun_flag = rx_done && rx_full;

  assign timeout_flag = (timeout_bit_counter == timeout_bits);

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      timeout_tick_counter <= 0;
      timeout_bit_counter  <= 0;
    end else if (baudtick) begin
      if (rx_done) begin
        timeout_bit_counter <= 0;
      end else if (timeout_tick_counter == SC-1) begin
        timeout_tick_counter <= 0;
        if (timeout_flag)
          timeout_bit_counter <= 0;
        else
          timeout_bit_counter <= timeout_bit_counter + 1'b1;
      end else begin
        timeout_tick_counter <= timeout_tick_counter + 1'b1;
      end
    end
  end
endmodule


module BAUDGEN
(
    input   wire        clk,
    input   wire        rst_n,
    input   wire [15:0] prescale, 
    input   wire        en,
    output  wire        baudtick
);
  ef_util_ticker #(.W(16)) baud_ticker (
    .clk(clk),
    .rst_n(rst_n),
    .en(en),
    .clk_div(prescale),
    .tick(baudtick)
  );
endmodule

/*
    UART Receiver
*/
module UART_RX #(parameter NUM_SAMPLES = 16, MDW = 8)(
    input   wire            clk,
    input   wire            resetn,
    input   wire            b_tick,             // Baud generator tick
    input   wire [3:0]      data_size,          // 5 - 9
    input   wire            stop_bits_count,    // 0: 1, 1: 2
    input   wire [2:0]      parity_type,        // 000: None, 001: odd, 010: even, 
                                                // 100: Sticky 0, 101: Sticky 1
    input   wire            rx,                 // RS-232 data port
    input   wire [MDW-1:0]  match_data,
    output  reg             rx_done,            // Transfer completed
    output  reg             parity_error,       // Parity Error
    output  reg             frame_error,        // Framing Error
    output  reg             break_flag,         // Break flag
    output  reg             match_flag,
    output  wire [MDW-1:0]  dout                // Received data
);
  localparam IDLE = 3'd0, START = 3'd1, DATA = 3'd2,
             PARITY = 3'd3, STOP = 3'd4;

  reg [2:0] state;
  reg [31:0] sample_counter;
  reg [31:0] data_index;
  reg [31:0] data_count;
  reg [MDW-1:0] data_reg;
  reg parity_bad;
  reg stop_bad;
  reg stop_index;
  reg [3:0] low_samples;
  reg expected_parity;
  integer i;

  assign dout = data_reg;

  always @* begin
    expected_parity = 1'b0;
    case (parity_type)
      3'b001: expected_parity = ~(^data_reg);
      3'b010: expected_parity =  (^data_reg);
      3'b100: expected_parity = 1'b0;
      3'b101: expected_parity = 1'b1;
      default: expected_parity = 1'b0;
    endcase
  end

  always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
      state            <= IDLE;
      sample_counter   <= 0;
      data_index       <= 0;
      data_count       <= 8;
      data_reg         <= {MDW{1'b0}};
      parity_bad       <= 1'b0;
      stop_bad         <= 1'b0;
      stop_index       <= 1'b0;
      low_samples      <= 0;
      rx_done          <= 1'b0;
      parity_error     <= 1'b0;
      frame_error      <= 1'b0;
      break_flag       <= 1'b0;
      match_flag       <= 1'b0;
    end else begin
      rx_done      <= 1'b0;
      parity_error <= 1'b0;
      frame_error  <= 1'b0;
      break_flag   <= 1'b0;
      match_flag   <= 1'b0;

      if (b_tick) begin
        case (state)
          IDLE: begin
            if (!rx) begin
              state          <= START;
              sample_counter <= 0;
              data_index     <= 0;
              data_count     <= (data_size >= 5 && data_size <= 9) ? data_size : 8;
              data_reg       <= {MDW{1'b0}};
              parity_bad     <= 1'b0;
              stop_bad       <= 1'b0;
              stop_index     <= 1'b0;
            end
          end

          START: begin
            if (sample_counter >= ((NUM_SAMPLES/2) > 0 ? (NUM_SAMPLES/2)-1 : 0)) begin
              sample_counter <= 0;
              state <= DATA;
            end else begin
              sample_counter <= sample_counter + 1'b1;
            end
          end

          DATA: begin
            if (sample_counter == NUM_SAMPLES-1) begin
              sample_counter <= 0;
              data_reg[data_index] <= rx;
              if (data_index == data_count-1) begin
                data_index <= 0;
                if (parity_type != 3'b000)
                  state <= PARITY;
                else begin
                  state <= STOP;
                  stop_index <= 1'b0;
                end
              end else begin
                data_index <= data_index + 1'b1;
              end

              if (!rx) begin
                if (low_samples == 4'd11)
                  break_flag <= 1'b1;
                if (low_samples < 4'd12)
                  low_samples <= low_samples + 1'b1;
              end else begin
                low_samples <= 0;
              end
            end else begin
              sample_counter <= sample_counter + 1'b1;
            end
          end

          PARITY: begin
            if (sample_counter == NUM_SAMPLES-1) begin
              sample_counter <= 0;
              parity_bad <= (parity_type == 3'b001 ||
                             parity_type == 3'b010 ||
                             parity_type == 3'b100 ||
                             parity_type == 3'b101) &&
                            (rx != expected_parity);
              state <= STOP;

              if (!rx) begin
                if (low_samples == 4'd11)
                  break_flag <= 1'b1;
                if (low_samples < 4'd12)
                  low_samples <= low_samples + 1'b1;
              end else begin
                low_samples <= 0;
              end
            end else begin
              sample_counter <= sample_counter + 1'b1;
            end
          end

          STOP: begin
            if (sample_counter == NUM_SAMPLES-1) begin
              sample_counter <= 0;
              if (!rx) begin
                if (low_samples == 4'd11)
                  break_flag <= 1'b1;
                if (low_samples < 4'd12)
                  low_samples <= low_samples + 1'b1;
              end else begin
                low_samples <= 0;
              end

              if (stop_bits_count && !stop_index) begin
                stop_bad   <= !rx;
                stop_index <= 1'b1;
              end else begin
                rx_done      <= 1'b1;
                parity_error <= parity_bad;
                frame_error  <= stop_bits_count && stop_bad;
                match_flag   <= (data_reg == match_data);
                state        <= IDLE;
              end
            end else begin
              sample_counter <= sample_counter + 1'b1;
            end
          end

          default: begin
            state <= IDLE;
          end
        endcase
      end
    end
  end
endmodule

/*
    UART Transmitter
*/
module UART_TX #(parameter NUM_SAMPLES = 16, MDW = 8)(
    input   wire                clk,
    input   wire                resetn,
    input   wire                tx_start,        
    input   wire                b_tick,             //baud rate tick
    input   wire [3:0]          data_size,          // 5 - 9
    input   wire                stop_bits_count,    // 0: 1, 1: 2
    input   wire [2:0]          parity_type,        // 000: None, 001: odd, 010: even, 
                                                    // 100: Sticky 0, 101: Sticky 1
    input   wire [MDW-1:0]      d_in,               // input data to transmit
    output  reg                 tx_done,            // Transfer finished
    output  wire                tx                  // output data to RS-232
);
  localparam IDLE = 3'd0, START = 3'd1, DATA = 3'd2,
             PARITY = 3'd3, STOP = 3'd4;

  reg [2:0] state;
  reg [31:0] tick_counter;
  reg [31:0] data_index;
  reg [31:0] data_count;
  reg [31:0] stop_index;
  reg [MDW-1:0] data_reg;
  reg [MDW-1:0] tx_data;
  reg serial_reg;
  reg parity_bit;

  assign tx = serial_reg;

  always @* begin
    case (parity_type)
      3'b001: parity_bit = ~(^d_in[data_count-1:0]);
      3'b010: parity_bit =  (^d_in[data_count-1:0]);
      3'b100: parity_bit = 1'b0;
      3'b101: parity_bit = 1'b1;
      default: parity_bit = 1'b0;
    endcase
  end

  always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
      state       <= IDLE;
      tick_counter <= 0;
      data_index  <= 0;
      data_count  <= 8;
      stop_index  <= 0;
      data_reg    <= {MDW{1'b0}};
      serial_reg  <= 1'b1;
      tx_done     <= 1'b0;
    end else begin
      tx_done <= 1'b0;

      case (state)
        IDLE: begin
          serial_reg <= 1'b1;
          if (tx_start) begin
            state        <= START;
            tick_counter <= 0;
            data_index   <= 0;
            data_count   <= (data_size >= 5 && data_size <= 9) ? data_size : 8;
            data_reg     <= d_in;
            stop_index   <= 0;
          end
        end

        START: begin
          serial_reg <= 1'b0;
          if (b_tick) begin
