    always @* begin
        tmr_reg_next = tmr_reg;
        if (tmr_start) begin
            if (tmr_mode == 2'b01)
                tmr_reg_next = tmr_reload;
            else if (tmr_mode == 2'b10 || tmr_mode == 2'b11)
                tmr_reg_next = 0;
        end else if (tmr_run) begin
            if (tmr_mode == 2'b01) begin
                if (tmr_eq_zero)
                    tmr_reg_next = tmr_periodic ? tmr_reload : tmr_reg;
                else
                    tmr_reg_next = tmr_reg - 1;
            end else if (tmr_mode == 2'b10) begin
                if (tmr_eq_reload)
                    tmr_reg_next = tmr_periodic ? 0 : tmr_reg;
                else
                    tmr_reg_next = tmr_reg + 1;
            end else if (tmr_mode == 2'b11) begin
                if (tmr_dir)
                    tmr_reg_next = tmr_reg + 1;
                else
                    tmr_reg_next = tmr_reg - 1;
