  wire start_pulse;
  ef_util_ped start_detector (
      .clk(clk),
      .in(tmr_en),
      .out(start_pulse)
  );

  reg [PRW-1:0] pr;
  wire tick = (pr == {PRW{1'b0}});

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
      pr <= {{(PRW-1){1'b0}}, 1'b1};
    else if (!tmr_en)
      pr <= prescaler;
    else if (pr == {PRW{1'b0}})
      pr <= prescaler;
    else
      pr <= pr - {{(PRW-1){1'b0}}, 1'b1};
