  reg direction_up;
  reg running;

  assign tmr = tmr_reg;
  assign matchx_flag = (tmr_reg == cmpx);
  assign matchy_flag = (tmr_reg == cmpy);
  assign timeout_flag = direction_up ?
                        (tmr_reg == tmr_reload) :
                        (tmr_reg == 32'd0);

