    if (!rst_n)
      tmr_reg <= 32'd0;
    else if (start_pulse)
      tmr_reg <= (tmr_cfg[1:0] == 2'b01) ? tmr_reload : 32'd0;
    else if (tmr_en && tick && running) begin
      if (tmr_start && (tmr_cfg[1:0] == 2'b01))
        tmr_reg <= tmr_reload;
      else if (tmr_start &&
               ((tmr_cfg[1:0] == 2'b10) ||
                (tmr_cfg[1:0] == 2'b11)))
        tmr_reg <= 32'd0;
      else begin
        case (tmr_cfg[1:0])
          2'b11: begin
            if (direction_up)
              tmr_reg <= tmr_reg + 32'd1;
            else
              tmr_reg <= tmr_reg - 32'd1;
