  wire e0 = eq_zero && !eq_cmpx && !eq_cmpy && !eq_reload;
  wire e1 = direction_up && eq_cmpx && !eq_zero && !eq_cmpy && !eq_reload;
  wire e2 = direction_up && eq_cmpy && !eq_zero && !eq_cmpx && !eq_reload;
  wire e3 = eq_reload && !eq_zero && !eq_cmpx && !eq_cmpy;
  wire e4 = !direction_up && eq_cmpy && !eq_zero && !eq_cmpx && !eq_reload;
  wire e5 = !direction_up && eq_cmpx && !eq_zero && !eq_cmpy && !eq_reload;

  reg [1:0] pwm0_action;
  reg [1:0] pwm1_action;
  reg [2:0] event_count;
  always @* begin
    event_count = {2'b00, e0} + {2'b00, e1} + {2'b00, e2} +
                  {2'b00, e3} + {2'b00, e4} + {2'b00, e5};
